function dungeonOrigin(){const d=sim.dungeon;if(!d)return{x0:0,y0:0,x1:1,y1:1};let x0=Infinity,y0=Infinity,x1=-Infinity,y1=-Infinity;for(const room of d.rooms){x0=Math.min(x0,room.x);y0=Math.min(y0,room.y);x1=Math.max(x1,room.x+room.width-1);y1=Math.max(y1,room.y+room.height-1)}for(const c of d.corridors){for(const p of c.cells){x0=Math.min(x0,p.x);y0=Math.min(y0,p.y);x1=Math.max(x1,p.x);y1=Math.max(y1,p.y)}}return{x0,y0,x1,y1}}
const dungeonCanvasStyle=computed(()=>{const o=dungeonOrigin();return{width:`${(o.x1-o.x0+1)*DUNGEON_PITCH}px`,height:`${DUNGEON_TOP+(o.y1-o.y0+1)*DUNGEON_PITCH}px`}});
const dungeonCells=computed(()=>{const out:{x:number;y:number;kind:'wall'|'floor'|'door';zone:'room'|'corridor'}[]=[];const d=sim.dungeon;if(!d)return out;const has=(x:number,y:number)=>out.some(c=>c.x===x&&c.y===y);const doorAt=(x:number,y:number)=>d.doors.some(door=>(door.roomCell.x===x&&door.roomCell.y===y)||(door.corridorCell.x===x&&door.corridorCell.y===y));for(const room of d.rooms){for(let ly=0;ly<room.interior.length;ly++){const row=room.interior[ly];for(let lx=0;lx<row.length;lx++){const ch=row[lx];if(ch==='#'||ch==='.'){const gx=room.x+lx;const gy=room.y+ly;if(!has(gx,gy))out.push({x:gx,y:gy,kind:ch==='#'?'wall':doorAt(gx,gy)?'door':'floor',zone:'room'})}}}}for(const c of d.corridors){for(const p of c.cells){if(!has(p.x,p.y))out.push({x:p.x,y:p.y,kind:doorAt(p.x,p.y)?'door':'floor',zone:'corridor'})}}return out});
function dungeonCellStyle(x:number,y:number){const o=dungeonOrigin();return{left:`${(x-o.x0)*DUNGEON_PITCH}px`,top:`${DUNGEON_TOP+(y-o.y0)*DUNGEON_PITCH}px`,width:`${DUNGEON_TILE}px`,height:`${DUNGEON_TILE}px`}}
function dungeonPosStyle(x:number,y:number){const o=dungeonOrigin();return{left:`${(x-o.x0)*DUNGEON_PITCH}px`,top:`${DUNGEON_TOP+(y-o.y0)*DUNGEON_PITCH}px`}}
function dungeonMarkerStyle(x:number,y:number){const o=dungeonOrigin();return{left:`${(x-o.x0)*DUNGEON_PITCH+DUNGEON_TILE/2}px`,top:`${DUNGEON_TOP+(y-o.y0)*DUNGEON_PITCH}px`}}
