function dungeonLabelStyle(room:{x:number;y:number;width:number}){const o=dungeonOrigin();return{left:`${(room.x+room.width/2-o.x0)*DUNGEON_PITCH}px`,top:`${DUNGEON_TOP+(room.y-o.y0)*DUNGEON_PITCH-42}px`}}
function dungeonRoomLabel(type:string){const labels:Record<string,string>={start:'START · 起点',combat:'COMBAT · 战斗',event:'EVENT · 事件',exit:'EXIT · 出口'};return labels[type]??type}
function dungeonShortRoom(id:string|null|undefined){if(!id)return id===null?'走廊':'—';const room=sim.dungeon?.rooms.find(r=>r.id===id);return room?dungeonRoomLabel(room.type):id}const EDITOR_LINE_HEIGHT=23.8;
