function chapterName(id:string){return id.startsWith('0-')?'启动教学':id.startsWith('1-')?'条件决策':id.startsWith('2-')?'状态记忆':'防御战术'}
function constraintHint(){const c=expeditionScenario.value?.constraint;if(!c)return '';const parts:string[]=[];if(c.require?.length)parts.push('需要包含：'+c.require.join(' '));if(c.forbid?.length)parts.push('禁用：'+c.forbid.join(' '));return parts.join(' ｜ ')}
function storyLessonText(id:string){if(id==='0-1')return '这一关只需要让机器人一直向前。先运行示例，确认你看到了出口。';if(id==='0-2')return '撞到墙不会前进，所以先用 wall_ahead() 问路，再决定转弯还是前进。';if(id==='1-1')return '史莱姆挡路时要先攻击；没有敌人时，再处理墙和移动。';if(id==='2-1')return '变量会记住之前的 Tick。walls 可以记录遇到过几次墙，帮助机器人改变路线。';if(id==='2-2')return '用 bool 变量记住上一次选择，让机器人在两个路口做不同的转向。';if(id==='3-1')return '先用 enemy_near() 感知两格内的敌人；敌人近身就用 ranged_attack() 先手点掉，否则继续前进。';if(id==='3-2')return '敌人每拍都会反击：用 bool 记住上一次选择，交替使用 shield() 挡下伤害和 attack() 削减敌人。';return '重试并观察 Trace，找出代码与地图不匹配的地方。'}
function expeditionNodeName(node:string){return ({combat:'遭遇战',elite:'精英',event:'事件',shop:'商店',rest:'整备',branch:'分岔',boss:'BOSS'} as Record<string,string>)[node]??node}
function routeNodeNoun(node:string|undefined){if(node==='event')return '异常事件';if(node==='shop')return '补给商店';if(node==='rest')return '整备点';if(node==='branch')return '路线分岔';return '路线节点'}
function routeNodeDescription(node:string|undefined){if(node==='event')return '未知遗迹等待你的决定。';if(node==='shop')return '用 credits 换取下一段路的优势。';if(node==='rest')return '就地整备能安全恢复耐久，不消耗 credits。';if(node==='branch')return '选择保守路线或精英捷径，决定下一站的风险与收益。';return '选择路线行动继续前进。'}
function enemyKindName(kind?:string){const names:Record<string,string>={slime:'史莱姆',swarm:'蜂群',turret:'炮台',tank:'重装核心',runner:'冲刺者',guard:'护盾守卫'};return names[kind??'']??'未知'}
function enemySpriteFor(kind?:string){const map:Record<string,string>={slime:slimeSprite,swarm:swarmSprite,turret:turretSprite,tank:tankSprite,runner:runnerSprite,guard:guardSprite};return map[kind??'']??slimeSprite}
function actionName(action?:string){return action?`${actionNames[action]??action} · ${action}`:'无动作'}
function eventName(event:string){if(event.startsWith('WATCHPOINT:'))return `监视点：${event.slice(11)}`;return eventNames[event]??event}
function itemAt(x:number,y:number){return sim.items.find(i=>i.x===x&&i.y===y)}
function isVisible(x:number,y:number){const range=gameMode.value==='expedition'?(expeditionModifiers.value.nearRange??2):2;return Math.abs(x-sim.robot.x)+Math.abs(y-sim.robot.y)<=range}
const fogEnabled=computed(()=>gameMode.value==='expedition'&&expeditionScenarioActive.value);
function localizeMessage(message:string){
  const exact:Record<string,string>={Ready:'系统就绪',Running:'固件运行中',Paused:'模拟已暂停',Stopped:'模拟已停止','Build succeeded':'构建成功，可以运行','Exit reached':'任务完成：已抵达出口','Robot destroyed':'任务失败：机器人已损毁','Source changed; build required':'源码已修改，请重新构建','Slime hit':'攻击命中史莱姆','Slime destroyed':'史莱姆已被消灭','Enemy strike':'敌人接触攻击：本拍受到伤害','Snapshot saved':'快照已保存','Rolled back to snapshot':'已回滚至快照','Hot reload applied':'热重载已应用','Example loaded':'已载入本关示例','Route node loaded':'已载入远征节点','Reference solution loaded':'参考解已载入，可运行演示','Scenario loaded':'战场已载入','Ranged hit':'远程命中敌人','Target destroyed':'目标已摧毁','Enemy heavy strike':'敌人重击','Energy depleted':'能量耗尽，部署失败'};
  if(exact[message])return exact[message];
  if(message.startsWith('Build error '))return message.replace('Build error ','构建错误 ');
  if(message.startsWith('Runtime error '))return message.replace('Runtime error ','运行错误 ');
  if(message.startsWith('Breakpoint set at line '))return `已在第 ${message.slice(23)} 行设置断点`;
  if(message.startsWith('Breakpoint hit at line '))return `程序在第 ${message.slice(23)} 行命中断点`;
  if(message.startsWith('Watchpoint changed: '))return `监视变量 ${message.slice(20)} 已变化，程序已暂停`;
  if(message.startsWith('Watchpoint set: '))return `已添加监视变量 ${message.slice(16)}`;
  if(message==='Watchpoints cleared')return '已清除全部监视变量';
  return message;
}
function syncEditorScroll(){editorScroll.value=editorRef.value?.scrollTop??0}
function handleEditorKeydown(event:KeyboardEvent){
  if(event.key!=='Tab'||running.value)return;
  event.preventDefault();
  const editor=event.currentTarget as HTMLTextAreaElement;
  const start=editor.selectionStart;
  const end=editor.selectionEnd;
  const value=editor.value;
  if(event.shiftKey){
    const lineStart=value.lastIndexOf('\n',Math.max(0,start-1))+1;
    const remove=value.slice(lineStart,lineStart+2)==='  '?2:value[lineStart]===' '?1:0;
    if(remove){editor.setRangeText('',lineStart,lineStart+remove,'preserve');editor.dispatchEvent(new Event('input',{bubbles:true}));editor.setSelectionRange(Math.max(lineStart,start-remove),Math.max(lineStart,start-remove));}
    return;
  }
  editor.setRangeText('  ',start,end,'end');
  editor.dispatchEvent(new Event('input',{bubbles:true}));
}
function beep(kind:'run'|'success'|'fail'='run'){if(!audioEnabled.value||typeof window==='undefined')return;try{const AudioContextClass=window.AudioContext||(window as typeof window & {webkitAudioContext?:typeof AudioContext}).webkitAudioContext;if(!AudioContextClass)return;const ctx=new AudioContextClass();const oscillator=ctx.createOscillator();const gain=ctx.createGain();oscillator.type='square';oscillator.frequency.value=kind==='success'?660:kind==='fail'?150:330;gain.gain.setValueAtTime(.025,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.12);oscillator.connect(gain);gain.connect(ctx.destination);oscillator.start();oscillator.stop(ctx.currentTime+.12)}catch{}}
function dismissTutorial(){tutorialVisible.value=false;try{window.localStorage.setItem('coderogue.tutorial.dismissed','1')}catch{}}
function showTutorial(){tutorialStep.value=0;tutorialVisible.value=true;try{window.localStorage.removeItem('coderogue.tutorial.dismissed')}catch{}}
function finishTutorial(){gameMode.value='story';expeditionScenarioActive.value=false;sim.selectLevel(0);loadLevelExample(0);build();dismissTutorial()}
function loadReferenceSolution(){if(gameMode.value!=='expedition'||!expeditionScenario.value)return;if(!autoDemo.value&&referenceUsed.value){sim.message='本局已使用过参考解，请尝试自己修正固件';return}const sol=expeditionScenario.value.solutionCode??expeditionScenario.value.starterCode;code.value=sol;built.value=false;buildError.value='';sim.status='idle';sim.message='Reference solution loaded';levelNotice.value='已载入参考解，可直接运行演示';if(!autoDemo.value)referenceUsed.value=true;try{window.localStorage.setItem('coderogue.firmware',code.value);window.localStorage.setItem('coderogue.firmware-level','expedition')}catch{}}
function loadLevelExample(index=sim.levelIndex){const level=STORY_LEVELS[index];const starter=expeditionScenarioActive.value?expeditionScenario.value?.starterCode:LEVEL_STARTER_CODE[level.id];code.value=starter??DEFAULT_CODE;built.value=false;buildError.value='';sim.status='idle';sim.message='Example loaded';levelNotice.value=expeditionScenarioActive.value?'已载入远征战场草稿，请补全关键逻辑':`已进入 ${levelName(level.id)} · 示例程序已载入`;try{window.localStorage.setItem('coderogue.firmware',code.value);window.localStorage.setItem('coderogue.firmware-level',expeditionScenarioActive.value?'expedition':level.id)}catch{}}
function prepareLevel(){loadLevelExample();build()}
function tutorialNext(){tutorialStep.value=Math.min(2,tutorialStep.value+1)}
function tutorialBack(){tutorialStep.value=Math.max(0,tutorialStep.value-1)}
function build(){if(roguePrototypeActive.value){const locked=findLockedCapability(code.value,rogueProtoState.capabilities);if(locked){built.value=false;buildError.value=`ABILITY LOCKED: ${locked}()`;sim.status='error';sim.message=`ABILITY LOCKED: ${locked}()`;return}}const result=sim.build(code.value);built.value=result.ok;buildError.value=result.ok?'':sim.message;sim.status=result.ok?'idle':'error';if(result.ok){try{window.localStorage.setItem('coderogue.firmware',code.value);buildHistory.value=[new Date().toLocaleTimeString(),...buildHistory.value].slice(0,5);window.localStorage.setItem('coderogue.build-history',JSON.stringify(buildHistory.value))}catch{}}}
function hotReload(){if(roguePrototypeActive.value){const locked=findLockedCapability(code.value,rogueProtoState.capabilities);if(locked){sim.message=`ABILITY LOCKED: ${locked}()`;sim.status='error';return}if(rogueProtoState.debugPoints<1){sim.message='NOT ENOUGH DEBUG POINTS';return}}const result=sim.hotReload(code.value);built.value=result.ok;buildError.value=result.ok?'':sim.message;if(result.ok){running.value=false;clearTimer();recordFinalRogueDebugEvent('Hot Reload 已应用');if(roguePrototypeActive.value){spendDebugPoints(rogueProtoState,1);rogueProtoState.stats.hotReloadCount+=1}if(tacticalRunActive.value){markRunFirmwareRevision(tacticalRunState);markRunDebugIntervention(tacticalRunState)};if(finalShowcaseActive.value){finalStats.hotReloadCount+=1;finalStats.debugInterventions+=1}}}
function markCodeDirty(){built.value=false;buildError.value='';if(sim.status!=='paused')sim.status='idle';sim.message='Source changed; build required';try{window.localStorage.setItem('coderogue.firmware',code.value)}catch{}}
function clearTimer(){if(timer!==undefined){clearInterval(timer);timer=undefined}}
function persistProgress(){saveStoryProgress(sim.getProgress(),storage)}
function completeExpeditionBattle(manualRewardId?:string){if(gameMode.value!=='expedition'||!expeditionNeedsFirmware.value||expedition.nodeCleared)return;const damage=Math.max(0,maxHp.value-sim.robot.hp);const energyUsed=Math.max(0,maxEnergy.value-sim.robot.energy);const actions=sim.frames.filter(frame=>!!frame.action).length;const sensorReads=sim.frames.reduce((sum,frame)=>sum+frame.sensors.length,0);const battleReport=gradeBattleReport({tick:sim.tick,damage,energyUsed,actions,sensorReads});battleGrade.value=battleReport.grade;lastBattleReport.value=battleReport;const node=expeditionNode.value;const creditsBefore=expedition.stats.credits;const enemyMaxHp=(expeditionScenario.value?defenseDemo.value&&expeditionNode.value==='boss'?expeditionScenario.value:scaleExpeditionBattle(expeditionScenario.value,expedition.nodeIndex):expeditionScenario.value)?.enemy?.hp??0;if(!expedition.resolveBattle(sim.tick,damage,enemyMaxHp,battleGrade.value,manualRewardId))return;selectedExpeditionAction.value=undefined;const reward=expedition.lastOutcome.rewardTitle;if(node==='boss'){expedition.clearNode();summaryVisible.value=true}else{expedition.clearNode();resetExpeditionFirmware()}sim.message=`固件 ${battleReport.grade} 级(${battleReport.score}分) · ${battleReport.reasons.join(' · ')} · 已${manualRewardId?'选择':'直接获得'} ${reward} · 资源 +${expedition.stats.credits-creditsBefore}`}
function noteExpeditionEnd(){if(gameMode.value!=='expedition'||!expeditionNeedsFirmware.value||expedition.nodeCleared)return;if(sim.status==='failed'){expedition.failDeployment();if(!referenceUsed.value)referenceHelpUnlocked.value=true;if(expedition.hull<=0){runLost.value=true;summaryVisible.value=true}}}
function persistStoryQuality(){if(gameMode.value!=='story'||sim.status!=='success')return;const damage=Math.max(0,5-sim.robot.hp);const energyUsed=Math.max(0,20-sim.robot.energy);const actions=sim.frames.filter(frame=>!!frame.action).length;const sensorReads=sim.frames.reduce((sum,frame)=>sum+frame.sensors.length,0);const report=gradeBattleReport({tick:sim.tick,damage,energyUsed,actions,sensorReads});if(recordStoryBest(currentLevel.value.id,report.grade,sim.tick,storage)){storyBest.bestGrades[currentLevel.value.id]=report.grade;storyBest.bestTicks[currentLevel.value.id]=sim.tick;const bonus={S:6,A:3,B:1}[report.grade]??0;if(bonus>0){meta.credits+=bonus;saveMeta(meta,storage)}sim.message=`任务完成 · 新纪录 ${report.grade} · ${sim.tick} Tick${bonus?` · 评价奖励 +${bonus}`:''}`}}
function startTimer(){clearTimer();timer=window.setInterval(()=>{finalRoguePreStep();sim.step();if(finalShowcaseActive.value){exposeTickInFinal();handleFinalEncounterTick();}if(finalRogueActive.value&&finalRogue.isCombatPhase())handleFinalRogueTick();selected.value=Math.max(0,sim.frames.length-1);if(sim.status!=='running'){running.value=false;clearTimer();persistProgress();if(finalRogueActive.value){if(sim.status==='failed'||sim.status==='error'){beep('fail');recordFinalRogueDebugRun(false);finalRogueNotice.value='战斗终止：机体损毁或运行错误'}return}if(sim.status==='success'){if(defenseDemo.value&&expeditionNode.value==='elite'&&!expedition.nodeCleared){openDefenseEliteReward();return}if(tacticalRunActive.value&&tacticalRunState.phase==='battle'){handleTacticalRunSuccess();beep('success');return}if(roguePrototypeActive.value&&rogueProtoState.phase==='battle'){handleRogueProtoSuccess();beep('success');return}persistStoryQuality();completeExpeditionBattle();beep('success')}if(sim.status==='failed'||sim.status==='error'){beep('fail');noteExpeditionEnd()}}},speed.value)}
function run(){if(finalRogueActive.value&&!finalRogue.isCombatPhase()){sim.message='请先完成当前 Reward / Branch / Rest 选择';return}if(gameMode.value==='expedition'&&!expeditionNeedsFirmware.value){sim.message='这是路线节点，请先选择上方行动';return}if(!built.value)build();if(!built.value)return;sim.reset();injectTacticalCarryOver();injectRogueProtoCarryOver();injectFinalRobot();injectFinalRogueCarryOver();persistProgress();selected.value=0;running.value=true;stepMode.value=false;beep('run');startTimer()}
function stepOnce(){if(finalRogueActive.value&&!finalRogue.isCombatPhase()){sim.message='请先完成当前 Reward / Branch / Rest 选择';return}if(running.value||gameMode.value==='expedition'&&!expeditionNeedsFirmware.value)return;if(tacticalRunActive.value&&tacticalRunState.phase==='battle')markRunDebugIntervention(tacticalRunState);if(!built.value)build();if(!built.value)return;if(sim.status==='idle'||sim.status==='success'||sim.status==='failed'||sim.status==='error')sim.reset();injectTacticalCarryOver();injectRogueProtoCarryOver();injectFinalRobot();injectFinalRogueCarryOver();sim.status='running';finalRoguePreStep();sim.step();if(finalShowcaseActive.value){exposeTickInFinal();handleFinalEncounterTick();}if(finalRogueActive.value&&finalRogue.isCombatPhase())handleFinalRogueTick();selected.value=Math.max(0,sim.frames.length-1);if(sim.status==='success'){if(tacticalRunActive.value&&tacticalRunState.phase==='battle'){handleTacticalRunSuccess();beep('success');return}if(roguePrototypeActive.value&&rogueProtoState.phase==='battle'){handleRogueProtoSuccess();beep('success');return}persistStoryQuality();completeExpeditionBattle();beep('success')}if(sim.status==='failed'||sim.status==='error'){beep('fail');if(finalRogueActive.value)recordFinalRogueDebugRun(false);noteExpeditionEnd()};stepMode.value=true}
function pulse(){if(sim.usePulse()){selected.value=Math.max(0,sim.frames.length-1);beep('run')}}
function manualRepair(){if(sim.useRepair()){selected.value=Math.max(0,sim.frames.length-1);beep('run')}}
const repairAvailable=computed(()=>gameMode.value==='expedition'&&expeditionNeedsFirmware.value&&sim.robot.hp<maxHp.value&&sim.robot.energy>=4&&(sim.status==='running'||sim.status==='paused'));
function handleGlobalKey(event:KeyboardEvent){const target=event.target as HTMLElement|null;if(target?.tagName==='TEXTAREA'||target?.tagName==='INPUT'||target?.isContentEditable)return;if(event.code==='Space'){event.preventDefault();if(running.value||sim.status==='paused')togglePause()}else if(event.key.toLowerCase()==='n'&&(gameMode.value==='expedition'||gameMode.value==='dungeon')){event.preventDefault();stepOnce()}}
function stop(){running.value=false;clearTimer();sim.status='idle';sim.message='Stopped'}
function togglePause(){if(sim.status==='paused'){sim.resume();running.value=true;beep('run');startTimer()}else if(sim.status==='running'){sim.pause();running.value=false;clearTimer()}}
function setBp(){if(breakpoint.value){sim.setBreakpoint(breakpoint.value);sim.message=`Breakpoint set at line ${breakpoint.value}`;if(tacticalRunActive.value&&tacticalRunState.phase==='battle')markRunDebugIntervention(tacticalRunState)}}
function clearBp(){sim.clearBreakpoints();sim.message='Breakpoints cleared'}
function setWatch(){if(sim.setWatchpoint(watchVariable.value)){sim.message=`Watchpoint set: ${watchVariable.value.trim()}`;watchVariable.value='';if(tacticalRunActive.value&&tacticalRunState.phase==='battle')markRunDebugIntervention(tacticalRunState)}}
function clearWatch(){sim.clearWatchpoints();sim.message='Watchpoints cleared'}
function takeSnapshot(){snapshotState=sim.snapshot();hasSnapshot.value=true;sim.message='Snapshot saved';recordFinalRogueDebugEvent('Snapshot 已保存');if(tacticalRunActive.value&&tacticalRunState.phase==='battle')markRunDebugIntervention(tacticalRunState)}
function rollback(){if(roguePrototypeActive.value&&rogueProtoState.debugPoints<2){sim.message='NOT ENOUGH DEBUG POINTS';return}if(snapshotState){sim.rollback(snapshotState);recordFinalRogueDebugEvent('Rollback 已执行');selected.value=Math.max(0,sim.frames.length-1);running.value=false;clearTimer();if(roguePrototypeActive.value){spendDebugPoints(rogueProtoState,2);rogueProtoState.stats.rollbackCount+=1}if(tacticalRunActive.value&&tacticalRunState.phase==='battle')markRunDebugIntervention(tacticalRunState);if(finalShowcaseActive.value){finalStats.rollbacks+=1;finalStats.debugInterventions+=1}}}
function chooseReward(id:string){selectedReward.value=id}
function chooseAndConfirmReward(id:string){chooseReward(id);confirmReward()}
function chooseExpeditionAction(id:string){selectedExpeditionAction.value=id}
function enterExpeditionScenario(loadExample=true){const scenario=expeditionScenario.value;if(!scenario)return;expeditionScenarioActive.value=true;referenceHelpUnlocked.value=false;runLost.value=false;lastBattleReport.value=undefined;const appliedScenario=defenseDemo.value&&expeditionNode.value==='boss'?scenario:scaleExpeditionBattle(scenario,expedition.nodeIndex);sim.setScenario(appliedScenario,expedition.modifiers(meta.upgrades),expedition.seed);running.value=false;clearTimer();selected.value=0;buildError.value='';if(loadExample){code.value=scenario.starterCode;built.value=false;levelNotice.value=`已载入${scenario.title}地图与示例固件`;try{window.localStorage.setItem('coderogue.firmware-level','expedition')}catch{}}}
function resetExpeditionFirmware(){stop();referenceHelpUnlocked.value=false;runLost.value=false;if(expeditionNeedsFirmware.value)enterExpeditionScenario(true);else{expeditionScenarioActive.value=true;sim.setScenario(expeditionScenario.value??EXPEDITION_HUB_SCENARIO,expedition.modifiers(meta.upgrades),expedition.seed);selected.value=0;built.value=false;code.value=EXPEDITION_HUB_SCENARIO.starterCode;sim.message='Route node loaded'}selected.value=0;buildError.value='';levelNotice.value=''}
function resolveExpeditionAction(){const actionId=selectedExpeditionAction.value;if(!actionId){sim.message='请先选择一个行动，再确认执行';return}if(expeditionNode.value==='branch'){if(expedition.chooseBranch(actionId)){selectedExpeditionAction.value=undefined;if(defenseDemo.value)defenseWaiting.value='';resetExpeditionFirmware()}return}if(expedition.resolveAction(actionId)){selectedExpeditionAction.value=undefined;if(defenseDemo.value&&expeditionNode.value==='shop'){defenseWaiting.value='shop-reward'}else if(defenseDemo.value){defenseWaiting.value=''};rewardModalVisible.value=true}else if(expeditionNode.value==='shop'&&actionId==='buy'){sim.message=`资源不足：购买补给需要 ${expedition.shopBuyCost()} credits`} }
function openRewardModal(){if(expedition.nodeCleared&&expeditionNode.value!=='boss')rewardModalVisible.value=true}
function confirmReward(){if(selectedReward.value){expedition.choose(selectedReward.value);expedition.clearNode();selectedReward.value=undefined;rewardModalVisible.value=false;if(defenseDemo.value)defenseWaiting.value='';resetExpeditionFirmware()}}
function level(index:number){stop();gameMode.value='story';expeditionScenarioActive.value=false;sim.selectLevel(index);loadLevelExample(index);persistProgress();selected.value=0;built.value=false}
function toggleMore(){moreOpen.value=!moreOpen.value}
function closeMore(){moreOpen.value=false}
function moreActiveDemo(kind:string){if(kind==='defense')return defenseDemo.value;if(kind==='tactical-run')return tacticalRunActive.value;if(kind==='rogue')return roguePrototypeActive.value;if(kind==='final-showcase')return finalShowcaseActive.value;if(kind==='tactical')return tacticalMode.value&&!tacticalRunActive.value&&!roguePrototypeActive.value&&!finalShowcaseActive.value;if(kind==='dungeon')return gameMode.value==='dungeon'&&!tacticalMode.value&&!finalRogueActive.value;return false}function showDungeonDemo(){leaveDefenseDemo();tacticalMode.value=false;stop();rewardModalVisible.value=false;summaryVisible.value=false;expeditionScenarioActive.value=false;gameMode.value='dungeon';sim.setScenario(DEMO_DUNGEON_SCENARIO);code.value=DEMO_DUNGEON_SCENARIO.starterCode;built.value=false;buildError.value='';selected.value=0;levelNotice.value='已载入固定 Dungeon Demo：Start → Combat → Event → Exit';sim.message='Scenario loaded'}
function loadDungeonStarter(){if(gameMode.value!=='dungeon')return;code.value=DEMO_DUNGEON_SCENARIO.starterCode;built.value=false;buildError.value='';sim.status='idle';sim.message='Dungeon starter loaded';levelNotice.value='示例固件已载入，可先运行观察' }
function showStoryMode(){leaveDefenseDemo();tacticalMode.value=false;stop();rewardModalVisible.value=false;summaryVisible.value=false;gameMode.value='story';expeditionScenarioActive.value=false;sim.selectLevel(sim.levelIndex);loadLevelExample(sim.levelIndex)}
function bankExpedition(){const finished=expedition.stats.victory||runLost.value||expedition.nodeIndex>=expedition.route.length;if(finished&&!autoDemoBanked.value){meta.credits+=expedition.stats.credits;if(expedition.stats.nodesCleared>0)meta.runs+=1;if(expedition.stats.victory&&battleGrade.value){const order=['S','A','B','C'];if(!meta.bestGrade||order.indexOf(battleGrade.value)<order.indexOf(meta.bestGrade))meta.bestGrade=battleGrade.value}}const latest={seed:expedition.seed,result:expedition.stats.victory?'victory':'lost',nodesCleared:expedition.stats.nodesCleared,routeLength:expedition.route.length,credits:expedition.stats.credits,rewards:expedition.rewards.map(r=>r.id),bestGrade:expedition.stats.victory?battleGrade.value:undefined};meta.lastRuns=[latest,...(meta.lastRuns??[])].slice(0,5);saveMeta(meta,storage)}
function purchaseUpgrade(id:string){const upgrade=metaUpgradesCatalog.find(item=>item.id===id);if(!upgrade||meta.upgrades.includes(id)||meta.credits<upgrade.cost)return;meta.credits-=upgrade.cost;meta.upgrades.push(id);saveMeta(meta,storage)}
const autoDemo=ref(false);
const autoDemoBanked=ref(false);
const defenseDemo=ref(false);
const defenseWaiting=ref<'branch'|'shop'|'elite-reward'|'pre-boss'|''>('');
const defenseRewardVisible=ref(false);
const defenseSelectedReward=ref<string>();let autoDemoTimer:number|undefined;
function stopAutoDemo(){autoDemo.value=false;if(autoDemoTimer!==undefined){clearInterval(autoDemoTimer);autoDemoTimer=undefined}}
function autoAdvance(){if(!autoDemo.value)return;if(gameMode.value!=='expedition'){stopAutoDemo();return}if(expedition.nodeIndex>=expedition.route.length){stopAutoDemo();return}if(defenseDemo.value&&(defenseRewardVisible.value||defenseWaiting.value))return;if(rewardModalVisible.value){chooseReward(expedition.choices()[0].id);confirmReward();return}if(summaryVisible.value){if(defenseDemo.value){stopAutoDemo()}else{summaryVisible.value=false}return}if(expeditionNeedsFirmware.value){if(defenseDemo.value&&!expeditionScenarioActive.value&&expeditionNode.value==='boss'){defenseWaiting.value='pre-boss';return}if(!expeditionScenarioActive.value){enterExpeditionScenario(true);return}if(sim.status==='idle'||sim.status==='error'||sim.status==='failed'){loadReferenceSolution();build();run()}}else if(!expedition.nodeCleared){if(defenseDemo.value&&expeditionNode.value==='branch'){defenseWaiting.value='branch';return}if(defenseDemo.value&&expeditionNode.value==='shop'){defenseWaiting.value='shop';return}if(!selectedExpeditionAction.value)chooseExpeditionAction(expedition.actions()[0].id);resolveExpeditionAction()}}
function leaveDefenseDemo(){defenseDemo.value=false;defenseWaiting.value='';defenseRewardVisible.value=false;defenseSelectedReward.value=undefined;stopAutoDemo();tacticalMode.value=false;leaveTacticalRunMode();leaveRoguePrototypeMode();leaveFinalShowcaseMode();leaveFinalRogueMode()}
function defenseWaitText(){const map:Record<string,string>={branch:'答辩暂停：请在 Branch 手动点击 risk，进入精英路线',shop:'答辩暂停：请在 Shop 手动选择行动','shop-reward':'答辩暂停：Shop 结算后请手动选择模块（建议 rewind 扩容电池）','elite-reward':'答辩暂停：战斗评级已出，请手动选择 Elite 战利品','pre-boss':'答辩暂停：Boss 前，请检查 hull/credits/构筑后开始'};return map[defenseWaiting.value]??''}
function openDefenseEliteReward(){if(!defenseDemo.value||expeditionNode.value!=='elite'||expedition.nodeCleared)return;const damage=Math.max(0,maxHp.value-sim.robot.hp);const energyUsed=Math.max(0,maxEnergy.value-sim.robot.energy);const actions=sim.frames.filter(frame=>!!frame.action).length;const sensorReads=sim.frames.reduce((sum,frame)=>sum+frame.sensors.length,0);const report=gradeBattleReport({tick:sim.tick,damage,energyUsed,actions,sensorReads});battleGrade.value=report.grade;lastBattleReport.value=report;defenseSelectedReward.value=undefined;defenseRewardVisible.value=true;defenseWaiting.value='elite-reward'}
function confirmDefenseBattleReward(rewardId:string){if(!defenseRewardVisible.value)return;defenseRewardVisible.value=false;defenseWaiting.value='';completeExpeditionBattle(rewardId);beep('success')}
function startDefenseBoss(){defenseWaiting.value='';enterExpeditionScenario(true)}
function startDefenseDemo(){leaveDefenseDemo();defenseDemo.value=true;defenseWaiting.value='';defenseRewardVisible.value=false;autoDemoBanked.value=true;expedition.reset(13);seedInput.value='13';showExpeditionMode(true);autoDemo.value=true;autoDemoTimer=window.setInterval(autoAdvance,900);autoAdvance()}
function resetDefenseDemo(){startDefenseDemo()}
function startAutoDemo(){stopAutoDemo();autoDemoBanked.value=true;autoDemo.value=true;autoDemoTimer=window.setInterval(autoAdvance,900);autoAdvance()}
function copySeed(){const text=seedInput.value.trim()||String(expedition.seed);if(typeof navigator!=='undefined'&&navigator.clipboard){navigator.clipboard.writeText(text)}sim.message=`种子 ${text} 已复制，可粘贴分享`}
function showTacticalShowcase(){leaveDefenseDemo();tacticalMode.value=true;tacticalIndex.value=0;loadTacticalScenario(0)}
function loadTacticalScenario(index:number){const sc=TACTICAL_SCENARIOS[index];if(!sc)return;stop();rewardModalVisible.value=false;summaryVisible.value=false;expeditionScenarioActive.value=false;gameMode.value='dungeon';tacticalMode.value=true;tacticalIndex.value=index;sim.setScenario({id:sc.id,title:sc.title,objective:sc.objective,starterCode:sc.starterCode,solutionCode:sc.finalCode,tactics:[sc.lesson],dungeon:sc.dungeon},sc.modifiers);code.value=sc.starterCode;built.value=false;buildError.value='';selected.value=0;levelNotice.value=sc.lesson;sim.message='Scenario loaded'}
function loadTacticalStarter(){if(!tacticalMode.value)return;const sc=TACTICAL_SCENARIOS[tacticalIndex.value];code.value=sc.starterCode;built.value=false;buildError.value='';sim.status='idle';sim.message='Tactical starter loaded'}
function loadTacticalFinal(){if(!tacticalMode.value)return;const sc=TACTICAL_SCENARIOS[tacticalIndex.value];code.value=sc.finalCode;built.value=false;buildError.value='';sim.status='idle';sim.message='Tactical reference loaded'}
const TACTICAL_TAGS=['RETREAT / KITE','CLOSE IN / MELEE','MINIMIZE EXPOSURE'];
function tacticalThemeName(){if(finalShowcaseActive.value)return'final-sector-'+finalSectorIndex.value;if(!tacticalMode.value)return'';return 'theme-'+TACTICAL_SCENARIOS[tacticalIndex.value].id.replace('-arena','')}
function dungeonEnemyCenterStyle(){const e=sim.enemy;const d=sim.dungeon;if(!d||e.hp<=0)return{};const o=dungeonOrigin();return{left:`${(e.x-o.x0+0.5)*DUNGEON_PITCH}px`,top:`${DUNGEON_TOP+(e.y-o.y0+0.5)*DUNGEON_PITCH}px`}}
function turretExposureStyle(){const e=sim.enemy;const d=sim.dungeon;if(!d||e.hp<=0||e.kind!=='turret')return{};const o=dungeonOrigin();const range=Math.max(1,e.range??3);return{left:`${(e.x-range-o.x0)*DUNGEON_PITCH}px`,top:`${DUNGEON_TOP+(e.y-o.y0)*DUNGEON_PITCH}px`,width:`${range*DUNGEON_PITCH}px`,height:`${DUNGEON_TILE}px`}}function leaveTacticalRunMode(){tacticalRunActive.value=false;runRewardVisible.value=false;runRestVisible.value=false;runCompleteVisible.value=false}
function applyRunState(s:TacticalRunState){tacticalRunState.roomIndex=s.roomIndex;tacticalRunState.phase=s.phase;tacticalRunState.hp=s.hp;tacticalRunState.energy=s.energy;tacticalRunState.modules=[...s.modules];tacticalRunState.firmwareCode=s.firmwareCode;tacticalRunState.clearedRooms=[...s.clearedRooms];tacticalRunState.stats={...s.stats}}
function startTacticalRun(){leaveDefenseDemo();leaveTacticalRunMode();tacticalMode.value=true;tacticalRunActive.value=true;gameMode.value='dungeon';applyRunState(createInitialTacticalRun());loadTacticalRunRoom(0,true);levelNotice.value='Tactical Run：Runner 首房使用 starter，之后 firmware 全程延续'}
function resetTacticalRun(){stop();runRewardVisible.value=false;runRestVisible.value=false;runCompleteVisible.value=false;gameMode.value='dungeon';tacticalMode.value=true;tacticalRunActive.value=true;applyRunState(createInitialTacticalRun());loadTacticalRunRoom(0,true)}
function loadTacticalRunRoom(index:number,allowStarter:boolean){const sc=TACTICAL_SCENARIOS[index];if(!sc)return;stop();rewardModalVisible.value=false;summaryVisible.value=false;expeditionScenarioActive.value=false;gameMode.value='dungeon';tacticalMode.value=true;tacticalRunActive.value=true;tacticalIndex.value=index;const mods=runRoomModifiers(sc.modifiers,tacticalRunState.modules);sim.setScenario({id:sc.id,title:sc.title,objective:sc.objective,starterCode:sc.starterCode,solutionCode:sc.finalCode,tactics:[sc.lesson],dungeon:sc.dungeon},mods);if(allowStarter)code.value=sc.starterCode;built.value=false;buildError.value='';selected.value=0;sim.message='Tactical Run room loaded'}
function injectTacticalCarryOver(){if(!tacticalRunActive.value||tacticalRunState.phase!=='battle')return;sim.robot.hp=Math.min(tacticalRunState.hp,sim.robot.hp);sim.robot.energy=Math.min(tacticalRunState.energy,sim.robot.energy)}
function handleTacticalRunSuccess(){if(!tacticalRunActive.value||tacticalRunState.phase!=='battle'||sim.status!=='success')return;const room=TACTICAL_SCENARIOS[tacticalIndex.value];const damage=Math.max(0,tacticalRunState.hp-sim.robot.hp);tacticalRunState.stats.totalTicks+=sim.tick;tacticalRunState.stats.damageTaken+=damage;tacticalRunState.stats.wins+=1;tacticalRunState.hp=sim.robot.hp;tacticalRunState.energy=sim.robot.energy;tacticalRunState.firmwareCode=code.value;if(!tacticalRunState.clearedRooms.includes(room.id))tacticalRunState.clearedRooms.push(room.id);if(tacticalRunState.roomIndex===0){tacticalRunState.roomIndex=1;tacticalRunState.phase='reward';runRewardVisible.value=true}else if(tacticalRunState.roomIndex===1){tacticalRunState.roomIndex=2;tacticalRunState.phase='rest';runRestVisible.value=true}else{tacticalRunState.roomIndex=TACTICAL_RUN_ROOM_COUNT;tacticalRunState.phase='complete';runCompleteVisible.value=true}}
function confirmTacticalRunReward(id:string){const choice=tacticalRewardChoices().find(reward=>reward.id===id);if(!choice||!runRewardVisible.value)return;if(!tacticalRunState.modules.includes(id))tacticalRunState.modules.push(id);tacticalRunState.phase='battle';tacticalRunState.phase='battle';runRewardVisible.value=false;loadTacticalRunRoom(tacticalRunState.roomIndex,false)}
function skipTacticalRunReward(){tacticalRunState.phase='battle';runRewardVisible.value=false;loadTacticalRunRoom(tacticalRunState.roomIndex,false)}
function applyTacticalRest(repair:boolean){if(!runRestVisible.value)return;if(repair){tacticalRunState.hp+=2;tacticalRunState.energy+=3}tacticalRunState.phase='battle';runRestVisible.value=false;loadTacticalRunRoom(tacticalRunState.roomIndex,false)}function resetTacticalScenario(){if(tacticalMode.value)loadTacticalScenario(tacticalIndex.value)}function leaveRoguePrototypeMode(){roguePrototypeActive.value=false;rogueRewardVisible.value=false;rogueCompleteVisible.value=false}
function applyRogueProtoState(s:RoguePrototypeState){rogueProtoState.roomIndex=s.roomIndex;rogueProtoState.phase=s.phase;rogueProtoState.hp=s.hp;rogueProtoState.energy=s.energy;rogueProtoState.debugPoints=s.debugPoints;rogueProtoState.debugPointBonus=s.debugPointBonus;rogueProtoState.firmwareCode=s.firmwareCode;rogueProtoState.capabilities=[...s.capabilities];rogueProtoState.selectedReward=s.selectedReward;rogueProtoState.stats={...s.stats}}
function startRoguePrototype(){leaveDefenseDemo();leaveTacticalRunMode();leaveRoguePrototypeMode();leaveFinalShowcaseMode();tacticalMode.value=true;gameMode.value='dungeon';roguePrototypeActive.value=true;applyRogueProtoState(createRoguePrototypeState());loadProtoRoom(0,true)}
function loadProtoRoom(index:number,first:boolean){const sc=ROGUE_PROTO_ROOMS[index];if(!sc)return;stop();rewardModalVisible.value=false;summaryVisible.value=false;expeditionScenarioActive.value=false;gameMode.value='dungeon';tacticalMode.value=true;roguePrototypeActive.value=true;rogueProtoState.roomIndex=index;rogueProtoState.phase='battle';tacticalIndex.value=0;sim.setScenario({id:sc.id,title:sc.title,objective:sc.objective,starterCode:sc.starterCode,solutionCode:sc.starterCode,tactics:[],dungeon:sc.dungeon},protoRoomModifiers(sc.modifiers));if(first){code.value=sc.starterCode;rogueProtoState.firmwareCode=sc.starterCode}built.value=false;buildError.value='';selected.value=0;resetPrototypeDebugPoints(rogueProtoState);sim.message='ROGUE PROTOTYPE room loaded'}
function injectRogueProtoCarryOver(){if(!roguePrototypeActive.value||rogueProtoState.phase!=='battle')return;sim.robot.hp=Math.min(rogueProtoState.hp,sim.robot.hp);sim.robot.energy=Math.min(rogueProtoState.energy,sim.robot.energy)}
function handleRogueProtoSuccess(){if(!roguePrototypeActive.value||rogueProtoState.phase!=='battle'||sim.status!=='success')return;rogueProtoState.hp=sim.robot.hp;rogueProtoState.energy=sim.robot.energy;rogueProtoState.firmwareCode=code.value;if(rogueProtoState.roomIndex===0){rogueProtoState.roomIndex=1;rogueProtoState.phase='reward';rogueRewardVisible.value=true}else{rogueProtoState.phase='complete';rogueCompleteVisible.value=true}}
function chooseRogueProtoReward(id:string){if(!rogueRewardVisible.value)return;applyProtoReward(rogueProtoState,id as any);rogueRewardVisible.value=false;rogueProtoState.hp=rogueProtoState.hp;loadProtoRoom(rogueProtoState.roomIndex,false)}
function resetRogueProtoRoom(){if(!roguePrototypeActive.value)return;rogueProtoState.stats.roomRetries+=1;loadProtoRoom(rogueProtoState.roomIndex,false)}
function protoLockedMessage(){const name=findLockedCapability(code.value,rogueProtoState.capabilities);return name?`ABILITY LOCKED: ${name}()`:''}
function protoCanHotReload(){return roguePrototypeActive.value?spendDebugPoints(rogueProtoState,1):true}function leaveFinalShowcaseMode(){finalShowcaseActive.value=false;finalShowcaseCompleteVisible.value=false}
function startFinalShowcase(){leaveDefenseDemo();leaveTacticalRunMode();leaveRoguePrototypeMode();leaveFinalShowcaseMode();leaveFinalShowcaseMode();tacticalMode.value=true;gameMode.value='dungeon';finalShowcaseActive.value=true;finalSectorIndex.value=0;finalSectorPhase.value='idle';finalFirePhase.value='first';finalClearMsg.value='';finalStats.hotReloadCount=0;finalStats.debugInterventions=0;finalStats.rollbacks=0;finalMetrics.baseline=undefined;finalMetrics.optimized=undefined;finalShowcaseCompleteVisible.value=false;loadFinalSector(0,true)}
function resetFinalSector(){if(!finalShowcaseActive.value)return;finalSectorPhase.value='idle';finalClearMsg.value='';finalMetrics.currentExposure=0;finalMetrics.currentDamage=0;loadFinalSector(finalSectorIndex.value,false,true)}
function loadFinalSector(index:number,first:boolean,restart=false){const enc=FINAL_ENCOUNTERS[index];if(!enc)return;stop();rewardModalVisible.value=false;summaryVisible.value=false;expeditionScenarioActive.value=false;gameMode.value='dungeon';tacticalMode.value=true;finalShowcaseActive.value=true;finalSectorIndex.value=index;finalSectorPhase.value='idle';finalClearMsg.value='';finalMetrics.currentExposure=0;finalMetrics.currentDamage=0;sim.setScenario({id:enc.id,title:enc.label,objective:enc.label,starterCode:enc.starterCode,solutionCode:enc.starterCode,tactics:[],dungeon:finalDungeon(enc)},enc.modifiers);if(first){code.value=enc.starterCode}else{/* firmware intentionally preserved across sectors */}built.value=false;buildError.value='';selected.value=0;sim.robot.x=enc.robot.x;sim.robot.y=enc.robot.y;sim.robot.dir=enc.robot.dir;const fullHp=enc.modifiers.maxHp??5;const fullEn=enc.modifiers.maxEnergy??20;finalEntryHp.value=restart?finalEntryHp.value:fullHp;finalEntryEnergy.value=restart?finalEntryEnergy.value:fullEn;sim.robot.hp=finalEntryHp.value;sim.robot.energy=finalEntryEnergy.value;finalStats.hp=sim.robot.hp;finalStats.energy=sim.robot.energy;if(index===2){snapshotState=sim.snapshot();hasSnapshot.value=true}sim.status='idle';sim.message=`SECTOR ONLINE: ${enc.label}`}
function injectFinalRobot(){if(!finalShowcaseActive.value)return;const enc=FINAL_ENCOUNTERS[finalSectorIndex.value];if(!enc)return;sim.robot.x=enc.robot.x;sim.robot.y=enc.robot.y;sim.robot.dir=enc.robot.dir;sim.robot.hp=Math.min(finalEntryHp.value,sim.robot.hp);sim.robot.energy=Math.min(finalEntryEnergy.value,sim.robot.energy);if(finalSectorIndex.value===2)finalMetrics.currentExposure=0}
function exposeTickInFinal(){if(!finalShowcaseActive.value||finalSectorIndex.value!==2)return;const d=Math.abs(sim.enemy.x-sim.robot.x)+Math.abs(sim.enemy.y-sim.robot.y);if(sim.enemy.hp>0&&d<=(FINAL_ENCOUNTERS[2].enemy.range??5))finalMetrics.currentExposure+=1}
function finalizeSectorClear(){const enc=FINAL_ENCOUNTERS[finalSectorIndex.value];if(finalSectorIndex.value===2){const optimized=code.value.includes('dash(');const metric={exposure:finalMetrics.currentExposure,hp:sim.robot.hp};if(optimized){finalMetrics.optimized=metric;finalStats.hp=sim.robot.hp;finalStats.energy=sim.robot.energy;finalShowcaseCompleteVisible.value=true;finalShowcaseActive.value=true}else{finalMetrics.baseline=metric;finalFirePhase.value='baseline-done';finalClearMsg.value=`BASELINE recorded: Exposure ${metric.exposure}, HP ${metric.hp}. Rollback and add dash.`}return}finalSectorPhase.value='cleared';finalStats.hp=sim.robot.hp;finalStats.energy=sim.robot.energy;finalClearMsg.value=`SECTOR CLEARED: ${enc.label}. OPENING NEXT SECTOR...`;window.setTimeout(()=>{loadFinalSector(finalSectorIndex.value+1,false)},700)}
function handleFinalEncounterTick(){if(!finalShowcaseActive.value||finalSectorPhase.value==='cleared')return;if(sim.enemy.hp<=0){running.value=false;clearTimer();finalizeSectorClear()}}
function loadFinalRunnerPatch(){if(finalSectorIndex.value===0&&finalShowcaseActive.value)code.value=FINAL_CODES.runnerPatch}
function loadFinalGuardPatch(){if(finalSectorIndex.value===1&&finalShowcaseActive.value)code.value=FINAL_CODES.guardPatch}
function loadFinalTurretBaseline(){if(finalSectorIndex.value===2&&finalShowcaseActive.value)code.value=FINAL_CODES.turretBaseline}
function loadFinalTurretOpt(){if(finalSectorIndex.value===2&&finalShowcaseActive.value)code.value=FINAL_CODES.turretOpt}
function showFinalComplete(){finalShowcaseCompleteVisible.value=true}function newExpedition(){stop();rewardModalVisible.value=false;summaryVisible.value=false;runLost.value=false;bankExpedition();const seedText=seedInput.value.trim();const parsed=Number(seedText);const seed=Number.isFinite(parsed)&&parsed>=0?Math.floor(parsed):Date.now();expedition.reset(seed);seedInput.value='';showExpeditionMode()}
function showExpeditionMode(keepDefense=false){if(!keepDefense)leaveDefenseDemo();stop();rewardModalVisible.value=false;summaryVisible.value=false;referenceUsed.value=false;autoDemoBanked.value=false;lastBattleReport.value=undefined;gameMode.value='expedition';if(expeditionNeedsFirmware.value)enterExpeditionScenario(true);else{expeditionScenarioActive.value=true;sim.setScenario(expeditionScenario.value??EXPEDITION_HUB_SCENARIO,expedition.modifiers(meta.upgrades),expedition.seed);sim.status='idle';sim.message='Route node loaded';built.value=false;code.value=EXPEDITION_HUB_SCENARIO.starterCode}}
let finalRogueSettling=false;
function leaveFinalRogueMode(){finalRogueActive.value=false;finalRogueCompleteVisible.value=false;finalRogueSettling=false}
function finalRogueStageIndex(){const idx=FINAL_ROGUE_ROUTE.indexOf(finalRogue.phase);return idx<0?FINAL_ROGUE_ROUTE.length-1:idx}
function finalRogueStageDone(stage:string){return finalRogueStageIndex()>FINAL_ROGUE_ROUTE.indexOf(stage)||finalRogue.phase==='complete'}
function finalRogueStageCurrent(stage:string){return stage===finalRogue.phase}
function finalRogueRewardStep(){return finalRogue.phase==='reward1'?1:finalRogue.phase==='reward2'?2:0}
function finalRogueModuleEffect(id:string){const map:Record<string,string>={regen:'Energy regen · 每 5 Tick +1 Energy',sonar:'感知范围 2 → 3 · 更早触发 enemy_near()',longshot:'ranged_attack() 射程 2 → 3',shield:'最大 HP +2 · 每次受伤 -1',rewind:'最大 Energy +10',dash:'移动能耗 1 → 0 · 最大 Energy 20 → 16'};return map[id]??''}
function finalRogueModuleCost(id:string){const map:Record<string,string>={regen:'代价：最大生命 -1 · 占模块位',sonar:'占模块位',longshot:'占模块位',shield:'代价：最大 Energy -4 · 占模块位',rewind:'占模块位',dash:'代价：最大 Energy -4 · 占模块位'};return map[id]??''}
function refreshFinalRogueMapFit(){if(!finalRogueActive.value||typeof document==='undefined')return;const wrap=document.querySelector<HTMLElement>('.final-rogue-map');if(!wrap||!sim.dungeon)return;const o=dungeonOrigin();const baseW=(o.x1-o.x0+1)*DUNGEON_PITCH;const baseH=DUNGEON_TOP+(o.y1-o.y0+1)*DUNGEON_PITCH;if(baseW<=0||baseH<=0)return;const availW=Math.max(80,wrap.clientWidth-12);const availH=Math.max(80,wrap.clientHeight-6);const scale=Math.max(.24,Math.min(1.12,availW/baseW,availH/baseH));finalRogueMapScale.value=scale;wrap.style.setProperty('--fr-scale',String(scale))}
function scheduleFinalRogueMapFit(){if(typeof window==='undefined')return;window.setTimeout(refreshFinalRogueMapFit,50)}
function finalRogueRecommended(id:string){return finalRogue.phase==='reward1'?id==='sonar':id==='dash'}
function finalRogueSafePreview(){return Math.min(finalRogue.maxEnergy,finalRogue.energy+10)}
function finalRogueRepairPreview(){return Math.min(finalRogue.maxHp,finalRogue.hp+4)}
function finalRogueChargePreview(){return Math.min(finalRogue.maxEnergy,finalRogue.energy+25)}
function finalRoguePreparedLoaded(){return finalRogueActive.value&&finalRogue.isCombatPhase()&&code.value===finalRoguePreparedCode()}
function finalRogueStrategyLabel(strategyCode:string){if(strategyCode===STANDARD_CODE)return '标准策略';if(strategyCode===ADAPTIVE_CODE)return '自适应策略';return '自写固件'}
function resetFinalRogueDebug(){finalRogueDebug.show=false;finalRogueDebug.events=[];finalRogueDebug.before=undefined;finalRogueDebug.after=undefined}
function recordFinalRogueDebugEvent(event:string){if(!finalRogueActive.value||finalRogue.phase!=='fire-control')return;if(!finalRogueDebug.events.includes(event))finalRogueDebug.events.push(event)}
function recordFinalRogueDebugRun(success:boolean){if(!finalRogueActive.value||finalRogue.phase!=='fire-control')return;const strategy=finalRogueStrategyLabel(code.value);const entry={strategy,success,hp:sim.robot.hp,energy:sim.robot.energy,ticks:sim.tick,damage:Math.max(0,finalRogueBattleEntry.hp-sim.robot.hp)};if(!success&&!finalRogueDebug.before){finalRogueDebug.before=entry;finalRogueDebug.show=true;return}if(success&&finalRogueDebug.before&&strategy==='自适应策略'&&!finalRogueDebug.after){finalRogueDebug.after=entry;finalRogueDebug.show=true}}
function loadFinalRogueDebugStrategy(strategyCode:string){if(!finalRogueActive.value||!finalRogue.isCombatPhase()||finalRogue.phase!=='fire-control')return;code.value=strategyCode;built.value=false;buildError.value='';sim.status='idle';sim.message='Prepared firmware loaded';finalRogueNotice.value=`已载入 ${finalRogueStrategyLabel(strategyCode)}（仅载入代码，尚未构建）`}
function finalRogueStageLabel(stage:string){return FINAL_ROGUE_STAGE_NAMES[stage]??stage}
function finalRogueModuleTitle(id:string){return FINAL_ROGUE_MODULE_META[id]?.title??id}
function finalRogueModuleDesc(id:string){return FINAL_ROGUE_MODULE_META[id]?.desc??''}
function finalRogueModuleKind(id:string){return FINAL_ROGUE_MODULE_META[id]?.kind??'MODULE'}
function finalRogueEnemyName(kind?:string){return FINAL_ROGUE_ENEMY_NAMES[kind??'']??'未知敌人'}
function finalRogueEnemyStatus(enemy:{active?:boolean;hp:number;x:number;y:number}){if(enemy.hp<=0)return{text:'已摧毁',cls:'down'};if(enemy.active===false)return{text:'未激活',cls:'dormant'};return{text:'已激活',cls:'active'}}
function finalRoguePreparedCode(){const map:Record<string,string>={pursuit:CONTROL_CODE,security:BREACH_CODE,'fire-control':ADAPTIVE_CODE};return map[finalRogue.phase]??''}
function loadPreparedFinalRogueFirmware(){if(!finalRogueActive.value||!finalRogue.isCombatPhase())return;code.value=finalRoguePreparedCode();built.value=false;buildError.value='';sim.status='idle';sim.message='Prepared Firmware loaded';levelNotice.value='Prepared Firmware 已载入，尚未构建或运行'}
function injectFinalRogueCarryOver(){if(!finalRogueActive.value||!finalRogue.isCombatPhase())return;const enc=finalRogue.currentEncounter();if(!enc)return;sim.robot.x=enc.robot.x;sim.robot.y=enc.robot.y;sim.robot.dir=enc.robot.dir;sim.robot.hp=Math.max(0,Math.min(finalRogue.hp,sim.robot.hp));sim.robot.energy=Math.max(0,Math.min(finalRogue.energy,sim.robot.energy))}
function loadFinalRogueCombat(){if(!finalRogueActive.value)return;const enc=finalRogue.currentEncounter();if(!enc)return;if(finalRogue.phase==='fire-control')resetFinalRogueDebug();stop();rewardModalVisible.value=false;summaryVisible.value=false;runRewardVisible.value=false;runRestVisible.value=false;runCompleteVisible.value=false;finalRogueCompleteVisible.value=false;expeditionScenarioActive.value=false;tacticalMode.value=false;gameMode.value='dungeon';const mods=finalRogue.combatModifiers();sim.setScenario({id:enc.id,title:enc.label,objective:`${finalRogueStageLabel(finalRogue.phase)} · 击破全部威胁`,starterCode:finalRoguePreparedCode(),solutionCode:finalRoguePreparedCode(),tactics:[],dungeon:rogueDungeon(enc),enemies:enc.enemies.map(e=>({...e}))},mods);sim.reset();sim.robot.x=enc.robot.x;sim.robot.y=enc.robot.y;sim.robot.dir=enc.robot.dir;finalRogueBattleEntry.hp=finalRogue.hp;finalRogueBattleEntry.energy=finalRogue.energy;sim.robot.hp=Math.min(finalRogue.maxHp,finalRogue.hp);sim.robot.energy=Math.min(finalRogue.maxEnergy,finalRogue.energy);code.value='';built.value=false;buildError.value='';selected.value=0;snapshotState=undefined;hasSnapshot.value=false;sim.status='idle';sim.message='Final Rogue combat loaded';levelNotice.value=`${finalRogueStageLabel(finalRogue.phase)}：点击 Prepared Firmware 载入准备固件，再构建并运行`;finalRogueNotice.value=`进入 ${finalRogueStageLabel(finalRogue.phase)} · HP ${finalRogue.hp}/${finalRogue.maxHp} · Energy ${finalRogue.energy}/${finalRogue.maxEnergy}`;scheduleFinalRogueMapFit()}
function finalRoguePreStep(){if(!finalRogueActive.value||!finalRogue.isCombatPhase())return;const enc=finalRogue.currentEncounter();if(!enc||sim.enemies.length<3)return;const third=sim.enemies[2];if(!third||third.active||third.hp<=0)return;const runner=sim.enemies.find(e=>e.kind==='runner');const guard=sim.enemies.find(e=>e.kind==='guard');if((guard&&guard.hp<=0)||(runner&&runner.hp<=0)||sim.robot.x>=enc.swarmActivateX)third.active=true}function handleFinalRogueTick(){if(!finalRogueActive.value||finalRogueSettling||!finalRogue.isCombatPhase())return;if(sim.enemies.length&&sim.enemies.every(e=>e.hp<=0)){recordFinalRogueDebugRun(true);finalRogueSettling=true;running.value=false;clearTimer();settleFinalRogueBattle()}}
function settleFinalRogueBattle(){if(!finalRogueActive.value)return;const firmware=code.value||finalRoguePreparedCode();const result=finalRogue.runNextCombat(firmware);finalRogueSettling=false;sim.status='idle';sim.message='区域肃清，行动继续';beep('success');finalRogueNotice.value=result?.success?`${finalRogueStageLabel(result?finalRogue.phase:'')} · 区域肃清`:`战斗结算失败，Run 已停止`;if(finalRogue.phase==='complete'){finalRogueCompleteVisible.value=true;return}if(finalRogue.phase==='failed'){sim.message='Final Rogue failed';return}if(finalRogue.phase==='reward1'||finalRogue.phase==='reward2'){return}if(finalRogue.isCombatPhase()){loadFinalRogueCombat()};scheduleFinalRogueMapFit()}
function chooseFinalRogueReward(id:string){if(!finalRogueActive.value)return;if(!finalRogue.chooseReward(id)){sim.message='模块选择失败';return}finalRogueNotice.value=`已选择 ${finalRogueModuleTitle(id)} · 当前模块 ${finalRogue.modules.join('、')}`;scheduleFinalRogueMapFit()}
function chooseFinalRogueBranch(choice:'safe'|'risk'){if(!finalRogueActive.value||!finalRogue.chooseBranch(choice))return;finalRogueNotice.value=choice==='safe'?'稳妥路线：+10 Energy，Reward 2 不含 DASH':'高危路线：无额外 Energy，Reward 2 开放 DASH';if(finalRogue.isCombatPhase())loadFinalRogueCombat();scheduleFinalRogueMapFit()}
function chooseFinalRogueRest(choice:'repair'|'charge'){if(!finalRogueActive.value||!finalRogue.chooseRest(choice))return;finalRogueNotice.value=choice==='repair'?'战地维修：HP +4':'快速充能：Energy +25';if(finalRogue.isCombatPhase())loadFinalRogueCombat();scheduleFinalRogueMapFit()}
function startFinalRogue(){leaveDefenseDemo();leaveTacticalRunMode();leaveRoguePrototypeMode();leaveFinalShowcaseMode();leaveFinalRogueMode();stop();rewardModalVisible.value=false;summaryVisible.value=false;runRewardVisible.value=false;runRestVisible.value=false;runCompleteVisible.value=false;finalRogueCompleteVisible.value=false;expeditionScenarioActive.value=false;tacticalMode.value=false;gameMode.value='dungeon';finalRogueActive.value=true;finalRogue.reset();finalRogueNotice.value='Final Rogue Run 开始：追猎迷宫';loadFinalRogueCombat()}
function resetFinalRogue(){if(finalRogueActive.value){startFinalRogue()}}
function finalRogueThreatState(){if(!finalRogueActive.value)return[];return sim.enemies.map((e)=>({kind:e.kind,x:e.x,y:e.y,hp:e.hp,active:e.active,name:finalRogueEnemyName(e.kind),status:finalRogueEnemyStatus(e),distance:Math.abs(e.x-sim.robot.x)+Math.abs(e.y-sim.robot.y)}))}
function finalRogueModuleList(){return finalRogue.modules}
function finalRogueThreatRows(){return finalRogueThreatState()}
if(startupDemoMode==='final-rogue'){startFinalRogue()}else if(startupDemoMode==='final-showcase'){startFinalShowcase()}else if(startupDemoMode==='rogue-prototype'){startRoguePrototype()}else if(startupDemoMode==='tactical-run'){startTacticalRun()}else if(startupDemoMode==='tactical'){showTacticalShowcase()}else if(startupDemoMode==='defense'){startDefenseDemo()}else if(startupDemoMode==='dungeon'){showDungeonDemo()}else if(startupDemoMode==='story'){showStoryMode()}else{showExpeditionMode()}
onMounted(()=>{window.addEventListener('keydown',handleGlobalKey);window.addEventListener('resize',refreshFinalRogueMapFit);scheduleFinalRogueMapFit()});
onBeforeUnmount(()=>{clearTimer();window.removeEventListener('keydown',handleGlobalKey);window.removeEventListener('resize',refreshFinalRogueMapFit)});
</script>

<template>
  <main class="shell" :class="finalRogueActive?'final-rogue-shell':undefined" @click="moreOpen=false">
    <div v-if="summaryVisible" class="reward-modal-backdrop" @click.self="summaryVisible=false"><section class="reward-modal run-summary-modal"><div class="reward-modal-head"><div><span class="panel-kicker">EXPEDITION REPORT</span><h2>远征结算报告</h2></div><button class="modal-close" @click="summaryVisible=false" aria-label="关闭报告">×</button></div><div class="summary-grid"><span>种子 <b>{{expedition.seed}}</b></span><span>节点 <b>{{expedition.stats.nodesCleared}} / {{expedition.route.length}}</b></span><span>伤害 <b>{{expedition.stats.damageDealt}}</b></span><span>受伤 <b>{{expedition.stats.damageTaken}}</b></span><span>资源 <b>{{expedition.stats.credits}}</b></span><span>结果 <b>{{expedition.stats.victory?'胜利':'撤离'}}</b></span></div><div class="summary-route"><span v-for="(node,index) in expedition.route" :key="index">{{index+1}} {{expeditionNodeName(node)}}</span></div><div v-if="expedition.rewards.length" class="summary-rewards"><b>已装备模块：</b>{{expedition.rewards.map(r=>r.title).join('、')}}</div><div class="summary-log">行动轨迹：<span v-for="line in expedition.log.slice(-10)" :key="line">{{line}}</span></div><button class="confirm-reward modal-confirm" @click="summaryVisible=false">返回</button></section></div>
    <div v-if="defenseRewardVisible" class="reward-modal-backdrop"><section class="reward-modal defense-reward-modal"><div class="reward-modal-head"><div><span class="panel-kicker">ELITE BATTLE / GRADE REWARD</span><h2>精英战 · {{battleGrade}} 级奖励</h2></div><button class="modal-close" @click="defenseRewardVisible=false" aria-label="稍后选择">×</button></div><div class="reward-modal-outcome" v-if="lastBattleReport"><span>真实评级</span><b>{{lastBattleReport.grade}}（{{lastBattleReport.score}}分）</b><em>{{lastBattleReport.reasons.join(' · ')}}</em></div><p class="reward-modal-tip">手动选择要装入构筑的模块。确认后由现有 ExpeditionRun.choose 真实装入，并在后续节点生效。</p><div class="reward-cards"><button v-for="reward in expedition.choices()" :key="reward.id" @click="confirmDefenseBattleReward(reward.id)"><span class="reward-kind">{{reward.kind}}</span><strong>{{reward.title}}</strong><small>{{reward.description}}</small><i>选择模块并继续</i></button></div><button class="confirm-reward modal-confirm" @click="resetDefenseDemo">重置演示</button></section></div>    <div v-if="runRewardVisible" class="reward-modal-backdrop"><section class="reward-modal tactical-reward"><div class="reward-modal-head"><div><span class="panel-kicker">TACTICAL RUN · REWARD</span><h2>Runner 通关 · 选择模块</h2></div></div><p class="reward-modal-tip">模块会真实影响后续 Guard / Turret 房的 SimulationModifiers。</p><div class="reward-cards"><button v-for="reward in tacticalRewardChoices()" :key="reward.id" @click="confirmTacticalRunReward(reward.id)"><span class="reward-kind">{{reward.kind}}</span><strong>{{reward.title}}</strong><small>{{reward.description}}</small><i>选择并进入 Guard</i></button></div><button class="confirm-reward modal-confirm" @click="skipTacticalRunReward">暂不选模块</button></section></div>
    <div v-if="runRestVisible" class="reward-modal-backdrop"><section class="reward-modal"><div class="reward-modal-head"><div><span class="panel-kicker">TACTICAL RUN · REST</span><h2>Guard 通关 · 整备</h2></div></div><p class="reward-modal-tip">HP {{tacticalRunState.hp}} / Energy {{tacticalRunState.energy}}。可以选择修理恢复少量状态后进入 Turret。</p><div class="reward-cards"><button class="rest-card" @click="applyTacticalRest(true)"><span class="reward-kind">REST</span><strong>整备修理</strong><small>HP +2 · Energy +3</small><i>进入 Turret</i></button><button class="rest-card" @click="applyTacticalRest(false)"><span class="reward-kind">PUSH</span><strong>直接出发</strong><small>不恢复，立即进入 Turret</small><i>进入 Turret</i></button></div></section></div>
    <div v-if="runCompleteVisible" class="reward-modal-backdrop"><section class="reward-modal run-summary-modal"><div class="reward-modal-head"><div><span class="panel-kicker">TACTICAL RUN · COMPLETE</span><h2>Run Complete</h2></div></div><div class="summary-grid"><span>通关房 <b>{{tacticalRunState.clearedRooms.length}} / {{TACTICAL_RUN_ROOM_COUNT}}</b></span><span>总 Ticks <b>{{tacticalRunState.stats.totalTicks}}</b></span><span>受伤 <b>{{tacticalRunState.stats.damageTaken}}</b></span><span>剩余 HP <b>{{tacticalRunState.hp}}</b></span><span>剩余 Energy <b>{{tacticalRunState.energy}}</b></span><span>模块 <b>{{tacticalRunState.modules.length}}</b></span><span>Firmware Revisions <b>{{tacticalRunState.stats.hotReloads}}</b></span><span>Debugger Interventions <b>{{tacticalRunState.stats.debugInterventions}}</b></span></div><div class="summary-route"><span v-for="room in tacticalRunState.clearedRooms" :key="room">{{room}}</span></div><button class="confirm-reward modal-confirm" @click="resetTacticalRun">重新开始</button></section></div>    <div v-if="finalShowcaseCompleteVisible" class="reward-modal-backdrop"><section class="reward-modal run-summary-modal"><div class="reward-modal-head"><div><span class="panel-kicker">OPERATION BREAKPOINT · MISSION COMPLETE</span><h2>MISSION COMPLETE</h2></div></div><div class="summary-grid"><span>PURSUIT BAY <b>ADAPTED</b></span><span>SECURITY GATE <b>PATCHED</b></span><span>FIRE CONTROL <b>OPTIMIZED</b></span><span>Firmware Revisions <b>{{finalStats.hotReloadCount}}</b></span><span>Debugger Interventions <b>{{finalStats.debugInterventions}}</b></span><span>Rollbacks <b>{{finalStats.rollbacks}}</b></span><span>Final HP <b>{{finalStats.hp}}</b></span><span>Final Energy <b>{{finalStats.energy}}</b></span><span>Exposure Reduction <b>{{finalMetrics.baseline?.exposure??'?'}} → {{finalMetrics.optimized?.exposure??'?'}}</b></span><span>Optimized HP <b>{{finalMetrics.optimized?.hp??'?'}}</b></span></div><p class="mission-line">CODE DEFINES BEHAVIOR.<br>DEBUGGING CHANGES THE OUTCOME.</p><button class="confirm-reward modal-confirm" @click="startFinalShowcase">重新开始 Mission</button></section></div><div v-if="rogueRewardVisible" class="reward-modal-backdrop"><section class="reward-modal"><div class="reward-modal-head"><div><span class="panel-kicker">ROGUE PROTOTYPE · REWARD</span><h2>Room 1 完成 · 选择能力</h2></div></div><p class="reward-modal-tip">三种 build 都不提供数值 buff：它们改变你能写出的策略。</p><div class="reward-cards"><button @click="chooseRogueProtoReward('back')"><span class="reward-kind">MOVEMENT</span><strong>Backstep Driver</strong><small>Unlock action: back() · Retreat one tile without turning.</small><i>选择并进入 Room 2</i></button><button @click="chooseRogueProtoReward('threat')"><span class="reward-kind">SENSING</span><strong>Threat Scanner</strong><small>Unlock sensor: enemy_near() · nearRange = 2.</small><i>选择并进入 Room 2</i></button><button @click="chooseRogueProtoReward('patching')"><span class="reward-kind">RUNTIME</span><strong>Hot Patch Cache</strong><small>Each battle room: Debug Points 3 → 4.</small><i>选择并进入 Room 2</i></button></div></section></div>
    <div v-if="rogueCompleteVisible" class="reward-modal-backdrop"><section class="reward-modal run-summary-modal"><div class="reward-modal-head"><div><span class="panel-kicker">ROGUE PROTOTYPE COMPLETE</span><h2>Prototype Complete</h2></div></div><div class="summary-grid"><span>Reward Chosen <b>{{rogueProtoState.selectedReward==='back'?'Backstep Driver':rogueProtoState.selectedReward==='threat'?'Threat Scanner':rogueProtoState.selectedReward==='patching'?'Hot Patch Cache':'—'}}</b></span><span>Rooms Cleared <b>{{ROGUE_PROTOTYPE_ROOM_COUNT}} / {{ROGUE_PROTOTYPE_ROOM_COUNT}}</b></span><span>Debug Points Spent <b>{{rogueProtoState.stats.debugPointsSpent}}</b></span><span>Hot Reloads <b>{{rogueProtoState.stats.hotReloadCount}}</b></span><span>Rollbacks <b>{{rogueProtoState.stats.rollbackCount}}</b></span><span>Room Retries <b>{{rogueProtoState.stats.roomRetries}}</b></span><span>Remaining HP <b>{{rogueProtoState.hp}}</b></span><span>Remaining Energy <b>{{rogueProtoState.energy}}</b></span></div><button class="confirm-reward modal-confirm" @click="startRoguePrototype">重新开始</button></section></div>    <div v-if="rewardModalVisible" class="reward-modal-backdrop" @click.self="rewardModalVisible=false"><section class="reward-modal"><div class="reward-modal-head"><div><span class="panel-kicker">NODE CLEARED / 节点结算</span><h2>{{expeditionNodeName(expeditionNode??'')}} · 战利品</h2></div><button class="modal-close" @click="rewardModalVisible=false" aria-label="关闭结算">×</button></div><div class="reward-modal-outcome"><span>本次行动</span><b>{{expeditionLastLog}}</b><em>伤害 {{expedition.lastOutcome.damageDealt}} · 受伤 {{expedition.lastOutcome.damageTaken}} · 资源 {{expedition.lastOutcome.credits >= 0 ? '+' : ''}}{{expedition.lastOutcome.credits}}</em></div><p class="reward-modal-tip">选择一个模块装入机体。模块会在之后的节点持续生效，重复获得的模块会转化为额外资源。</p><div class="reward-cards"><button v-for="reward in expedition.choices()" :key="reward.id" :class="{selected:selectedReward===reward.id}" @click="chooseAndConfirmReward(reward.id)"><span class="reward-kind">{{reward.kind}}</span><strong>{{reward.title}}</strong><small>{{reward.description}}</small><i>{{selectedReward===reward.id?'已选择':'选择模块'}}</i></button></div><button class="confirm-reward modal-confirm" @click="confirmReward" :disabled="!selectedReward">{{selectedReward?'装入机体并继续':'请选择一个模块'}}</button></section></div>
    <div v-if="tutorialVisible" class="tutorial-backdrop"><section class="tutorial-card"><div class="tutorial-top"><span class="panel-kicker">FIRST BOOT / 新手引导</span><span class="tutorial-count">{{tutorialStep+1}} / 3</span></div><div v-if="tutorialStep===0"><h2>你不需要先学会 C++</h2><p>在这里，你只需要写下“机器人每一拍要做什么”。程序会重复执行，直到机器人抵达出口。</p><div class="tutorial-code"><code>void update() {</code><code>  move_forward();</code><code>}</code></div><p class="tutorial-note"><b>读法：</b>每次 update() 执行一次，move_forward() 就让机器人向前走一格。每行末尾的 <code>;</code> 表示这一句结束。</p></div><div v-else-if="tutorialStep===1"><h2>先问路，再行动</h2><p>传感器只负责回答问题，动作才会改变地图。你可以把它们理解成机器人的眼睛和手。</p><div class="tutorial-terms"><span><code>wall_ahead()</code><b>前面是墙吗？返回 是 / 否</b></span><span><code>enemy_ahead()</code><b>前面有敌人吗？返回 是 / 否</b></span><span><code>turn_right()</code><b>向右转，不会向前走</b></span><span><code>attack()</code><b>攻击正前方的史莱姆</b></span><span><code>enemy_near()</code><b>敌人在 2 格内时返回 是</b></span><span><code>ranged_attack()</code><b>攻击 2 格内的敌人</b></span><span><code>shield()</code><b>本拍抵挡下一次伤害</b></span></div><p class="tutorial-note"><b>重要：</b>每一拍只会提交第一个动作，先观察 Trace 再修改代码。</p></div><div v-else><h2>你的第一关只有一步</h2><p>示例会先自动载入并完成构建检查。之后点击“运行”，观察机器人抵达金色出口。</p><div class="tutorial-flow"><span><b>1</b><strong>载入示例</strong><small>获得一份能成功的程序</small></span><span><b>2</b><strong>构建检查</strong><small>检查拼写和括号</small></span><span><b>3</b><strong>运行模拟</strong><small>观察代码如何影响机器人</small></span></div><p class="tutorial-note">之后再尝试改一行代码，重新构建，看看结果有什么不同。关闭引导后，左侧“本关怎么想”下方有完整语法速查。</p></div><div class="tutorial-actions"><button v-if="tutorialStep>0" @click="tutorialBack">上一步</button><button class="quiet" @click="dismissTutorial">跳过引导</button><button v-if="tutorialStep<2" class="primary" @click="tutorialNext">下一步</button><button v-else class="primary" @click="finishTutorial">载入示例并检查</button></div></section></div>
        <header class="topbar app-header">
      <div class="brand-lockup brand-compact">
        <div class="brand-mark">CR</div>
        <div><div class="eyebrow">CODE ROGUE</div><h1>代码浪客 <span>CODE ROGUE</span></h1></div>
      </div>
      <nav class="app-nav" aria-label="主导航">
        <button :class="{active:gameMode==='story'}" @click="showStoryMode">教学</button>
        <button :class="{active:gameMode==='expedition'}" @click="showExpeditionMode">远征</button>
        <button :class="{active:finalRogueActive}" @click="startFinalRogue">Final Rogue</button>
      </nav>
      <div class="more-wrap" @click.stop>
        <button class="more-toggle" :class="{open:moreOpen}" @click="toggleMore">更多 ▾</button>
        <div v-if="moreOpen" class="more-menu">
          <button :class="{active:moreActiveDemo('defense')}" @click="closeMore();startDefenseDemo()">答辩演示</button>
          <button :class="{active:moreActiveDemo('tactical-run')}" @click="closeMore();startTacticalRun()">战术走廊</button>
          <button :class="{active:moreActiveDemo('rogue')}" @click="closeMore();startRoguePrototype()">Rogue 原型</button>
          <button :class="{active:moreActiveDemo('final-showcase')}" @click="closeMore();startFinalShowcase()">最终演示</button>
          <button :class="{active:moreActiveDemo('tactical')}" @click="closeMore();showTacticalShowcase()">战术房</button>
          <button :class="{active:moreActiveDemo('dungeon')}" @click="closeMore();showDungeonDemo()">地牢演示</button>
        </div>
      </div>
      <div class="run-summary header-hud">
        <div class="hud-status"><small>{{statusLabel}}</small><b>TICK {{sim.tick}}</b></div>
        <div class="vital hud-hp"><div><span>HP</span><b>{{displayHp}} / {{maxHp}}</b></div><i><em :style="{width:hpPercent}"></em></i></div>
        <div class="vital hud-energy"><div><span>Energy</span><b>{{displayEnergy}} / {{maxEnergy}}</b></div><i><em :style="{width:energyPercent}"></em></i></div>
      </div>
      <button class="settings-toggle" @click="settingsOpen=!settingsOpen" aria-label="打开设置">⚙ 设置</button>
    </header>
    <section v-if="settingsOpen" class="settings-panel"><label><input type="checkbox" v-model="audioEnabled" @change="()=>{try{window.localStorage.setItem('coderogue.audio',audioEnabled?'1':'0')}catch{}}"> 音效反馈</label><span>最近构建：{{buildHistory.length?buildHistory.join(' · '):'暂无记录'}} · 总资源 {{meta.credits}}</span><div class="run-history">最近远征：<span v-for="run in (meta.lastRuns??[])" :key="run.seed">{{run.result==='victory'?'胜利':'失联'}} · 种子{{run.seed}} · {{run.nodesCleared}}/{{run.routeLength}} · {{run.credits}} credits</span><span v-if="!(meta.lastRuns??[]).length">暂无记录</span></div><div class="run-history">Story 最佳：<span v-for="level in STORY_LEVELS" :key="level.id">{{level.id}} {{storyBest.bestGrades[level.id]||'—'}}</span></div><button @click="showTutorial">重新查看引导</button><div class="meta-upgrades"><span>机体升级</span><button v-for="u in metaUpgradesCatalog" :key="u.id" @click="purchaseUpgrade(u.id)" :disabled="meta.upgrades.includes(u.id)||meta.credits<u.cost" :title="u.description">{{u.title}}（{{u.cost}}）{{meta.upgrades.includes(u.id)?'已解锁':''}}</button></div></section>

    <section class="story-strip">

      <div v-if="gameMode==='story'" class="story-heading"><div><span>STORY MODE</span><strong>教学关卡</strong></div><div class="story-progress"><b>{{completedCount}}</b> / {{STORY_LEVELS.length}} 已完成</div></div>
      <nav v-if="gameMode==='story'" class="levels" aria-label="故事关卡">
        <button v-for="(item,index) in STORY_LEVELS" :key="item.id" :class="{active:index===sim.levelIndex,completed:sim.completedLevels.has(item.id)}" @click="level(index)">
          <span class="level-id">{{item.id}}</span><span class="level-copy"><b>{{levelName(item.id)}}</b><small>{{chapterName(item.id)}}</small></span><span class="level-state">{{storyBest.bestGrades[item.id]||(sim.completedLevels.has(item.id)?'✓':'›')}}</span>
        </button>
      </nav>
      <div v-if="gameMode==='story'" class="level-context"><div><span>当前关卡</span><strong>{{currentLevel.id}} · {{levelName(currentLevel.id)}}</strong><small>{{currentLevel.objective}}</small></div><button class="context-action" @click="prepareLevel" :disabled="running">载入示例并构建</button><em v-if="levelNotice">{{levelNotice}}</em></div>
    </section>

    <section v-if="gameMode==='expedition'" class="expedition-strip">
      <div class="expedition-head"><div><span>EXPEDITION · SEED {{expedition.seed}}</span><strong>远征路线</strong></div><div class="expedition-stats">节点 {{expedition.stats.nodesCleared}} / {{expedition.route.length}} · 本局资源 {{expedition.stats.credits}} · 耐久 {{expedition.hull}} / {{expedition.maxHull()}} · 总资源 {{meta.credits}} · 最佳 {{meta.bestGrade||'—'}}</div><div class="seed-controls"><input v-model="seedInput" type="number" inputmode="numeric" placeholder="种子" aria-label="远征种子"><button @click="newExpedition">新远征</button><button class="quiet" @click="copySeed">复制种子</button><button v-if="!autoDemo" class="auto-demo-button" @click="startAutoDemo">自动演示</button><button v-else class="auto-demo-button" @click="stopAutoDemo">停止演示</button></div></div>
      <div v-if="defenseDemo" class="defense-banner"><span>DEFENSE DEMO · seed {{expedition.seed}}</span><b>当前：{{expeditionNodeName(expeditionNode??'')}} · Hull {{expedition.hull}} · Credits {{expedition.stats.credits}} · 模块 {{expedition.rewards.length}} · 评级 {{battleGrade}}</b><em>{{defenseWaitText()||'非关键节点自动推进中…'}}</em><button @click="resetDefenseDemo">重置 seed=13</button></div>      <div v-if="expedition.rewards.length" class="reward-bag"><span>已装备构筑</span><b v-for="reward in expedition.rewards" :key="reward.id">{{reward.title}}</b></div>
      <div class="expedition-route"><span v-for="(node,index) in expedition.route" :key="index" :class="['route-node',index<expedition.nodeIndex||index===expedition.nodeIndex?`node-${node}`:'',{current:index===expedition.nodeIndex,cleared:index<expedition.nodeIndex,unknown:index>expedition.nodeIndex}]">{{index+1}}<small>{{index<=expedition.nodeIndex||defenseDemo||(meta.upgrades.includes('scout1')&&index<=expedition.nodeIndex+2)?expeditionNodeName(node):'?'}}</small></span></div>
      <div v-if="expeditionLastLog" class="expedition-log">最近行动 <b>{{expeditionLastLog}}</b></div>
      <div v-if="expeditionNode && !expedition.nodeCleared && !expeditionNeedsFirmware" class="encounter-row"><div class="encounter-copy"><b>{{routeNodeNoun(expeditionNode)}}</b><span>{{routeNodeDescription(expeditionNode)}}</span><small class="encounter-hint">此节点无需运行固件，请先选择一个行动</small></div><div class="encounter-actions"><button v-for="action in expeditionActions" :key="action.id" :class="{selected:selectedExpeditionAction===action.id}" @click="chooseExpeditionAction(action.id)"><b>{{action.title}}</b><small>{{action.description}}</small></button><button class="confirm-reward" @click="resolveExpeditionAction" :disabled="!selectedExpeditionAction">{{selectedExpeditionAction?'确认执行':'请选择行动'}}</button></div><div v-if="defenseDemo&&defenseWaiting" class="defense-pause-note">{{defenseWaitText()}}</div></div>
      <div v-else-if="expeditionNode && !expedition.nodeCleared && expeditionNeedsFirmware && (sim.status==='failed'||sim.status==='error')" class="encounter-row battle-failure"><div class="encounter-copy"><b>{{runLost?'船体归零 · 远征失联':sim.status==='failed'?'本次部署失效':'固件执行中断'}}</b><span>{{runLost?'你已经没有可用的船体继续本次远征，点击下方结束并保留战利品。':sim.status==='failed'?'敌方压制了机体。检查最后几帧，调整决策后重新部署。':'请依据控制台的行号修正固件，再回到战场。'}}</span><small class="encounter-hint">{{runLost?'船体受损无法修复，本局终止。':'本战尚未结算，不会跳过路线节点；损毁会扣除 1 船体。'}}</small></div><div class="encounter-actions"><button v-if="!runLost" class="confirm-reward" @click="enterExpeditionScenario(false)">保留代码重试</button><button v-if="!runLost" @click="enterExpeditionScenario(true)">载入战术示例</button><button v-else class="confirm-reward" @click="newExpedition">结束远征</button></div></div>
      <div v-else-if="expeditionNode && !expedition.nodeCleared && expeditionNeedsFirmware" class="encounter-row battle-gate"><div class="encounter-copy"><b>{{expeditionNode==='boss'?'终局 BOSS':expeditionNode==='elite'?'精英战场':'遭遇战'}}</b><span>这是一场真正的代码战斗：地图上的机器人需要击败敌人并抵达出口。</span><small class="encounter-hint">{{constraintHint()?`固件要求：${constraintHint()}`:`草稿不完整，请在下方补全逻辑并运行固件`}}</small></div><div class="encounter-actions"><button v-if="defenseDemo&&expeditionNode==='boss'" class="confirm-reward defense-start-boss" @click="startDefenseBoss" :disabled="expeditionScenarioActive">开始 Boss 战</button><button v-else class="confirm-reward" @click="enterExpeditionScenario(true)" :disabled="expeditionScenarioActive">{{expeditionScenarioActive?'已在战场中':'进入战场'}}</button></div><div v-if="defenseDemo&&defenseWaiting==='pre-boss'" class="defense-pause-note">Boss 前暂停：确认 hull / credits / 构筑后点击“开始 Boss 战”。</div></div>
      <div v-else-if="expeditionNode && expeditionNode!=='boss'" class="reward-row reward-pending"><span class="reward-label">节点已清除</span><div class="outcome-note">结算已准备<br><b>伤害 {{expedition.lastOutcome.damageDealt}} · 受伤 {{expedition.lastOutcome.damageTaken}} · 资源 {{expedition.lastOutcome.credits >= 0 ? '+' : ''}}{{expedition.lastOutcome.credits}}</b></div><button class="confirm-reward" @click="openRewardModal">打开战利品选择</button></div>
      <div v-else class="reward-row expedition-complete"><span>远征完成 · 伤害 {{expedition.stats.damageDealt}} · 受伤 {{expedition.stats.damageTaken}} · 资源 {{expedition.stats.credits}} · 模块 {{expedition.rewards.length}} · 本战评级 {{battleGrade}}</span><button @click="newExpedition">开启新远征</button></div>
    </section>

    <section v-if="gameMode==='expedition'" class="mission-brief"><div v-if="lastBattleReport" class="grade-card"><span>最近评级</span><b>{{lastBattleReport.grade}}（{{lastBattleReport.score}}分）</b><small>{{lastBattleReport.reasons.join(' · ')}}</small></div><div><span>当前任务</span><strong>{{expeditionScenario?.title??routeNodeNoun(expeditionNode)}}</strong><small>{{expeditionScenario?.objective??'选择路线决策，换取下一场战斗的优势。'}}</small></div><div class="brief-stat"><span>敌方强度</span><b v-if="expeditionScenario?.enemy && enemyVisible">{{enemyKindName(sim.enemy.kind)}} · {{sim.enemy.hp}} HP · {{sim.enemy.moveEvery?`每 ${sim.enemy.moveEvery} Tick 逼近`:'静止守卫'}}<br><small v-if="sim.enemy.attackEvery">{{sim.enemy.kind==='turret'?'远程每':'接触后每'}} {{sim.enemy.attackEvery}} Tick {{sim.enemy.kind==='turret'?'射击':'攻击'}}</small><em v-if="enemyAttackCountdown" class="attack-countdown">⚠ 下次攻击 {{enemyAttackCountdown}} Tick</em></b><b v-else-if="expeditionScenario?.enemy">⚠ 未知敌情（靠近后可见）</b><b v-else>无战斗</b></div><div class="brief-stat"><span>当前构筑</span><b>{{expedition.rewards.length?`${expedition.rewards.length} 个模块`: '标准机体'}}</b></div><div class="brief-stat"><span>胜利收益</span><b>{{expeditionNeedsFirmware?'固件评级越高奖励越多':'路线分支奖励'}}</b></div></section>

    <section v-if="gameMode==='dungeon'&&!finalRogueActive" class="expedition-strip">
      <div v-if="tacticalMode&&!tacticalRunActive&&!roguePrototypeActive&&!finalShowcaseActive" class="tactical-head"><div><span>TACTICAL SHOWCASE 2.0</span><strong>{{TACTICAL_SCENARIOS[tacticalIndex]?.title}} <em class="tactical-tag">{{TACTICAL_TAGS[tacticalIndex]}}</em></strong><small>{{TACTICAL_SCENARIOS[tacticalIndex]?.lesson}}</small></div><div class="seed-controls"><button v-for="(sc,i) in TACTICAL_SCENARIOS" :key="sc.id" :class="{active:i===tacticalIndex}" @click="loadTacticalScenario(i)">{{sc.title.split(' · ')[0]}}</button><button @click="loadTacticalStarter">载入 starter</button><button @click="loadTacticalFinal">载入 final</button><button class="quiet" @click="resetTacticalScenario">重置</button></div></div>
      <div v-else-if="finalShowcaseActive" class="final-banner"><div class="final-progress"><b class="final-node done">ENTRY</b><span>▼</span><b :class="['final-node',{current:finalSectorIndex===0,clear:finalSectorIndex>0}]">01 PURSUIT BAY</b><span>▼</span><b :class="['final-node',{current:finalSectorIndex===1,clear:finalSectorIndex>1}]">02 SECURITY GATE</b><span>▼</span><b :class="['final-node',{current:finalSectorIndex===2,clear:finalSectorIndex>2}]">03 FIRE CONTROL</b><span>▼</span><b class="final-node">CORE EXIT</b></div><div class="final-sector-copy"><span>{{FINAL_ENCOUNTERS[finalSectorIndex]?.phaseLabel}}</span><strong>{{FINAL_ENCOUNTERS[finalSectorIndex]?.label}} · {{FINAL_ENCOUNTERS[finalSectorIndex]?.slogan}}</strong><small v-if="finalClearMsg">{{finalClearMsg}}</small><small v-else>PATCH HINT: {{FINAL_ENCOUNTERS[finalSectorIndex]?.patchHint}}</small></div><div class="final-actions"><button @click="resetFinalSector">RESTART SECTOR</button><span v-if="finalSectorIndex===2" class="final-metrics">EXPOSURE {{finalMetrics.currentExposure}} · BASELINE {{finalMetrics.baseline?.hp!==undefined?('HP '+finalMetrics.baseline.hp+' / Exp '+finalMetrics.baseline.exposure):'—'}} · OPT {{finalMetrics.optimized?.hp!==undefined?('HP '+finalMetrics.optimized.hp+' / Exp '+finalMetrics.optimized.exposure):'—'}}</span></div></div><div v-else-if="roguePrototypeActive" class="rogue-proto-banner"><div><span>ROGUE PROTOTYPE</span><strong>Room {{rogueProtoState.roomIndex+1}} / {{ROGUE_PROTOTYPE_ROOM_COUNT}} · {{ROGUE_PROTO_ROOMS[rogueProtoState.roomIndex]?.title}}</strong><small>Phase {{rogueProtoState.phase}} · HP {{rogueProtoState.hp}} · Energy {{rogueProtoState.energy}} · Reward {{rogueProtoState.selectedReward?('Backstep Driver / Threat Scanner / Hot Patch Cache'):'Pending'}} · Firmware kept</small></div><div class="proto-debug"><b>DEBUG POINTS: {{rogueProtoState.debugPoints}} / {{rogueProtoState.debugPointBonus+3}}</b><button @click="resetRogueProtoRoom">Reset Room</button></div></div>
<div v-else-if="tacticalRunActive" class="tactical-run-banner"><div><span>TACTICAL RUN</span><strong>Room {{tacticalRunState.roomIndex+1}} / {{TACTICAL_RUN_ROOM_COUNT}} · {{TACTICAL_SCENARIOS[tacticalIndex]?.title}}</strong><small>Phase {{tacticalRunState.phase}} · HP {{tacticalRunState.hp}} · Energy {{tacticalRunState.energy}} · Modules {{tacticalRunState.modules.length}} · Firmware kept</small></div><button class="quiet" @click="resetTacticalRun">重置连跑</button></div>
      <div v-else class="expedition-head"><div><span>FIXED DUNGEON SLICE</span><strong>Start → Combat → Event → Exit</strong></div><div class="expedition-stats">当前：{{dungeonShortRoom(sim.robot.roomId)}} · 状态 {{statusLabel}} · Tick {{sim.tick}}</div><div class="seed-controls"><button @click="showDungeonDemo">重新载入</button><button @click="loadDungeonStarter">载入示例</button></div></div><div v-if="!tacticalMode" class="expedition-log"><b>目标：</b>{{DEMO_DUNGEON_SCENARIO.objective}}</div>
    </section>
    <section v-if="finalRogueActive" class="expedition-strip final-rogue-strip">
            <div class="expedition-head final-rogue-head">
        <div class="final-rogue-title"><span>FINAL ROGUE</span><strong>火控远征</strong></div>
        <div class="final-rogue-resources"><span class="module-label">模块<template v-if="finalRogue.modules.length"><b v-for="id in finalRogue.modules" :key="id" class="module-chip">{{finalRogueModuleTitle(id)}}</b></template><em v-else>标准机体</em></span><button class="final-danger" @click="resetFinalRogue">重新开始</button></div>
      </div>      <div class="final-rogue-route" aria-label="Final Rogue 路线">
        <span v-for="stage in FINAL_ROGUE_ROUTE" :key="stage" :class="['final-rogue-node',{current:finalRogueStageCurrent(stage),done:finalRogueStageDone(stage)}]">{{finalRogueStageDone(stage)?'✓ ':''}}{{finalRogueStageLabel(stage)}}</span>
      </div>
            <div v-if="finalRogue.isCombatPhase()" class="final-rogue-mission">
        <div class="mission-copy"><span>当前关卡</span><b>{{finalRogueStageLabel(finalRogue.phase)}}</b><em>击破全部威胁，继续远征</em></div>
        <div class="mission-threats">
          <div v-for="(threat,index) in finalRogueThreatState()" :key="index" :class="['mission-threat',threat.status.cls]">
            <b>{{threat.name}}</b><span>HP {{threat.hp}}</span><i>{{threat.status.text}}</i>
          </div>
        </div>
        <div class="mission-actions">
          <span class="prepared-state">{{finalRoguePreparedLoaded()?'Prepared Firmware 已载入，尚未构建':'Prepared Firmware 未载入'}}</span>
          <button class="final-primary" @click="loadPreparedFinalRogueFirmware">载入 Prepared Firmware</button>
          <template v-if="finalRogue.phase==='fire-control'"><button class="debug-strategy-button" @click="loadFinalRogueDebugStrategy(STANDARD_CODE)">标准策略</button><button class="debug-strategy-button" @click="loadFinalRogueDebugStrategy(ADAPTIVE_CODE)">自适应策略</button></template>
        </div>
      </div>      <div v-if="finalRogue.phase==='reward1'||finalRogue.phase==='reward2'" class="final-rogue-decision reward-decision">
        <div class="decision-head"><div><span>REWARD</span><strong>模块奖励 {{finalRogueRewardStep()}}</strong></div><small>选择会真实写入 RunState.modules，并在后续 Combat 应用 modifier。</small></div>
        <div class="reward-cards final-rogue-cards">
          <button v-for="id in finalRogue.rewardChoices()" :key="id" :class="{recommended:finalRogueRecommended(id)}" @click="chooseFinalRogueReward(id)">
            <span class="reward-kind">{{finalRogueModuleKind(id)}}<i v-if="finalRogueRecommended(id)">推荐</i></span>
            <strong>{{finalRogueModuleTitle(id)}}</strong>
            <b>{{finalRogueModuleEffect(id)}}</b>
            <small>{{finalRogueModuleCost(id)}} · {{finalRogueModuleDesc(id)}}</small>
            <i class="card-cta">选择并继续</i>
          </button>
        </div>
      </div>      <div v-else-if="finalRogue.phase==='branch'" class="final-rogue-decision branch-decision">
        <div class="decision-head"><div><span>ROUTE DECISION</span><strong>路线选择</strong></div><small>两条路线都由 FinalRogueRun.chooseBranch 真实结算。</small></div>
        <div class="route-cards">
          <button class="route-card safe" @click="chooseFinalRogueBranch('safe')"><span class="route-tag">稳妥路线</span><strong>稳妥路线</strong><dl><dt>Energy</dt><dd>{{finalRogue.energy}} → {{finalRogueSafePreview()}}</dd></dl><small>{{finalRogue.energy<finalRogue.maxEnergy?'获得 +10 Energy':'当前已到 Energy 上限，实际不再增加'}} · Reward 2 不包含 DASH</small><i>进入安保中心</i></button>
          <button class="route-card risk" @click="chooseFinalRogueBranch('risk')"><span class="route-tag">高危路线</span><strong>高危路线</strong><dl><dt>Energy</dt><dd>不额外增加</dd></dl><small>无 Energy 补给，但 Reward 2 会增加 DASH 候选</small><i>进入安保中心</i></button>
        </div>
      </div>      <div v-else-if="finalRogue.phase==='rest'" class="final-rogue-decision rest-decision">
        <div class="decision-head"><div><span>MAINTENANCE BAY</span><strong>维护舱</strong></div><small>维护舱调用现有 FinalRogueRun.chooseRest，只展示真实恢复预览。</small></div>
        <div class="route-cards">
          <button class="route-card repair" @click="chooseFinalRogueRest('repair')"><span class="route-tag">战地维修</span><strong>战地维修</strong><dl><dt>HP</dt><dd>{{finalRogue.hp}} → {{finalRogueRepairPreview()}} / {{finalRogue.maxHp}}</dd></dl><small>HP +4，恢复后到达 {{finalRogueRepairPreview()}} / {{finalRogue.maxHp}}</small><i>进入火控核心</i></button>
          <button class="route-card charge" @click="chooseFinalRogueRest('charge')"><span class="route-tag">快速充能</span><strong>快速充能</strong><dl><dt>Energy</dt><dd>{{finalRogue.energy}} → {{finalRogueChargePreview()}} / {{finalRogue.maxEnergy}}</dd></dl><small>Energy +25，恢复后到达 {{finalRogueChargePreview()}} / {{finalRogue.maxEnergy}}</small><i>进入火控核心</i></button>
        </div>
      </div>      <div v-else-if="finalRogue.phase==='complete'" class="encounter-row final-rogue-complete-row">
        <div class="encounter-copy"><b>行动完成</b><span>Final Rogue canonical 整局已真实完成。</span><small class="encounter-hint">统计来自 FinalRogueRun.stats 与最终 RunState。</small></div>
        <button class="final-primary" @click="finalRogueCompleteVisible=true">查看行动完成报告</button>
      </div>
      <div v-else-if="finalRogue.phase==='failed'" class="encounter-row battle-failure"><div class="encounter-copy"><b>战斗失败 · 行动终止</b><span>FinalRogueRun 状态停留在失败节点，未伪造通关。</span></div><button class="confirm-reward" @click="resetFinalRogue">重新开始 Final Rogue</button></div>
      <div v-if="finalRogueDebug.show" class="final-rogue-debug-comparison">
        <div class="debug-comparison-title"><span>调试对照</span><em>Snapshot / Rollback / Hot Reload</em></div>
        <div class="debug-runs">
          <div v-if="finalRogueDebug.before" class="debug-run debug-before"><span>调试前</span><b>{{finalRogueDebug.before.strategy}}</b><em :class="finalRogueDebug.before.success?'ok':'bad'">{{finalRogueDebug.before.success?'成功':'失败'}}</em><small>HP {{finalRogueDebug.before.hp}} · Damage {{finalRogueDebug.before.damage}} · Ticks {{finalRogueDebug.before.ticks}}</small></div>
          <div v-if="finalRogueDebug.after" class="debug-run debug-after"><span>调试后</span><b>{{finalRogueDebug.after.strategy}}</b><em :class="finalRogueDebug.after.success?'ok':'bad'">{{finalRogueDebug.after.success?'成功':'失败'}}</em><small>HP {{finalRogueDebug.after.hp}} · Damage {{finalRogueDebug.after.damage}} · Ticks {{finalRogueDebug.after.ticks}}</small></div>
        </div>
        <div class="debug-events"><span v-for="event in finalRogueDebug.events" :key="event" class="debug-event">{{event}}</span></div>
      </div>    </section>        <div v-if="finalRogueCompleteVisible&&finalRogueActive" class="reward-modal-backdrop"><section class="reward-modal run-summary-modal final-rogue-complete"><div class="reward-modal-head"><div><span class="panel-kicker">远征结算</span><h2>行动完成</h2></div><button class="modal-close" @click="finalRogueCompleteVisible=false" aria-label="关闭报告">×</button></div><div class="final-complete-stats"><div><b>{{finalRogue.stats.kills}}</b><span>击杀</span></div><div><b>{{finalRogue.stats.totalTicks}}</b><span>Ticks</span></div><div><b>{{finalRogue.stats.damageTaken}}</b><span>承受伤害</span></div><div><b>{{finalRogue.hp}} / {{finalRogue.maxHp}}</b><span>最终 HP</span></div><div><b>{{finalRogue.energy}} / {{finalRogue.maxEnergy}}</b><span>最终 Energy</span></div></div><div class="complete-modules"><span>Modules</span><b v-for="id in finalRogue.modules" :key="id" class="module-chip">{{finalRogueModuleTitle(id)}}</b><em v-if="!finalRogue.modules.length">无</em></div><p class="mission-line">击杀 {{finalRogue.stats.kills}} · 总 Ticks {{finalRogue.stats.totalTicks}} · 承伤 {{finalRogue.stats.damageTaken}}</p><button class="final-primary modal-confirm" @click="resetFinalRogue">重新开始 Final Rogue</button></section></div>    <section class="layout">
      <div class="left-column">
        <section class="panel editor-panel">
          <div class="panel-head"><div><span class="panel-kicker">FIRMWARE WORKBENCH</span><strong>固件编辑器</strong></div><div class="panel-tools"><span v-if="currentSourceLine" class="source-line">执行行 {{currentSourceLine}}</span><button v-if="gameMode!=='dungeon'" class="example-button" @click="loadLevelExample()" :disabled="running">{{gameMode==='expedition'?'载入战场草稿':'载入本关示例'}}</button><button v-else-if="gameMode==='dungeon'&&!finalRogueActive" class="example-button" @click="loadDungeonStarter" :disabled="running">载入 Dungeon 示例</button><button v-else-if="finalRogueActive" class="example-button" @click="loadPreparedFinalRogueFirmware" :disabled="running">Prepared Firmware</button><button v-if="gameMode==='expedition' && referenceHelpUnlocked" class="example-button solution-button" @click="loadReferenceSolution" :disabled="running">失败后可载入参考解</button><span class="chip">RoboC++</span></div></div>
          <div class="file-tab"><span class="file-dot"></span>firmware.cpp <small>{{built?'已构建':'未构建'}}</small></div>
          <div class="editor-shell">
            <div class="line-gutter" :style="{transform:`translateY(-${editorScroll}px)`}" aria-hidden="true"><span v-for="(_,index) in codeLines" :key="index" :class="{current:index+1===currentSourceLine}">{{index+1}}</span></div>
            <div v-if="currentSourceLine" class="line-highlight" :style="{top:`${EDITOR_PADDING+(currentSourceLine-1)*EDITOR_LINE_HEIGHT-editorScroll}px`}" aria-hidden="true"></div>
            <textarea ref="editorRef" v-model="code" spellcheck="false" aria-label="Firmware editor" :readonly="running" @keydown="handleEditorKeydown" @input="markCodeDirty" @scroll="syncEditorScroll"></textarea>
          </div>
          <div class="actions">
            <button class="primary" @click="build" :disabled="running || sim.status==='paused' || (gameMode==='expedition'&&!expeditionNeedsFirmware)"><span>⚙</span> 构建</button>
            <button v-if="sim.status==='paused'" @click="hotReload">{{roguePrototypeActive?'热重载 (1 DP)':'热重载'}}</button>
            <button class="run-button" @click="run" :disabled="running || sim.status==='paused' || (gameMode==='expedition'&&!expeditionNeedsFirmware)"><span>▶</span> 运行</button>
            <button @click="togglePause" :disabled="!running && sim.status!=='paused'"><span>{{sim.status==='paused'?'▶':'Ⅱ'}}</span> {{sim.status==='paused'?'继续':'暂停'}}</button>
            <button v-if="gameMode==='expedition'||gameMode==='dungeon'" :class="['step-button',{active:stepMode}]" @click="stepOnce" :disabled="running || (gameMode==='expedition'&&!expeditionNeedsFirmware)"><span>⏭</span> 单步</button>
            <button v-if="gameMode==='expedition'" class="pulse-button" @click="pulse" :disabled="!pulseAvailable"><span>✦</span> 脉冲干扰 <small>{{sim.pulseUsed?'已使用':'耗能 3'}}</small></button><button v-if="gameMode==='expedition'" class="pulse-button repair-button" @click="manualRepair" :disabled="!repairAvailable"><span>✚</span> 紧急修理 <small>耗能 4</small></button>
            <button class="quiet" @click="stop"><span>■</span> 停止</button>
            <label for="run-speed">速度<select id="run-speed" v-model.number="speed" aria-label="运行速度"><option :value="1000">1×</option><option :value="500">2×</option><option :value="250">4×</option></select></label>
          </div>
          <div v-if="gameMode==='story'||gameMode==='dungeon'" class="debug-controls">
            <span class="debug-title">断点调试</span><label for="breakpoint-line">源码行</label><input id="breakpoint-line" v-model.number="breakpoint" type="number" min="1" step="1" placeholder="3">
            <button @click="setBp" :disabled="!breakpoint">设置断点</button><button @click="clearBp" :disabled="!sim.breakpoints.size">清除</button>
            <span v-if="sim.breakpoints.size" class="breakpoint-list">生效行：{{Array.from(sim.breakpoints).sort((a,b)=>a-b).join(', ')}}</span><span v-else class="breakpoint-list muted">暂无断点</span>
            <span class="debug-divider"></span><label for="watch-variable">监视变量</label><input id="watch-variable" v-model="watchVariable" @keyup.enter="setWatch" placeholder="例如 n">
            <button @click="setWatch" :disabled="!watchVariable.trim()">添加</button><button @click="clearWatch" :disabled="!sim.watchpoints.size">清除</button>
            <span v-if="sim.watchpoints.size" class="watch-list"><b v-for="name in Array.from(sim.watchpoints)" :key="name">{{name}} = {{frame?.variables[name] === undefined ? '—' : String(frame.variables[name])}}</b></span><span v-else class="watch-list muted">暂无监视变量</span>
            <span class="debug-divider"></span><button @click="takeSnapshot">保存快照</button><button @click="rollback" :disabled="!hasSnapshot">{{roguePrototypeActive?'回滚 (2 DP)':'回滚'}}</button>
          </div>
        </section>

        <section v-if="gameMode==='expedition'" class="lesson-panel battle-advice"><div class="lesson-heading"><div><span class="panel-kicker">TACTICAL BRIEF</span><strong>{{expeditionNeedsFirmware?'战术情报':'路线情报'}}</strong></div><span>{{expeditionNeedsFirmware?'读局势，再写固件':'先选行动，再进入下一战'}}</span></div><p>{{expeditionNeedsFirmware?'每一拍只能执行一个动作。敌人接触机体会造成伤害，先把感知条件放在移动之前。':'这里是决策节点，不需要运行代码。你的选择会改变资源、耐久和下一场战斗的优势。'}}</p><ol><li v-for="tip in expeditionScenario?.tactics" :key="tip">{{tip}}</li></ol><div v-if="expeditionNeedsFirmware" class="api-guide"><div><code>enemy_ahead()</code><span>敌人在正前方时为 true</span></div><div><code>enemy_near()</code><span>敌人距离 ≤ 2 时为 true</span></div><div><code>attack()</code><span>攻击正前方的敌人</span></div><div><code>ranged_attack()</code><span>攻击 2 格内的敌人</span></div><div><code>shield()</code><span>本拍展开护盾，抵挡下一次伤害</span></div><div><code>wall_ahead()</code><span>前方是否被墙阻断</span></div><div><code>low_hp()</code><span>生命 ≤ 2 时为 true</span></div></div></section>
                <section v-else-if="finalRogueActive" class="lesson-panel battle-advice final-rogue-brief"><div class="lesson-heading"><div><span class="panel-kicker">FINAL ROGUE BRIEF</span><strong>{{finalRogueStageLabel(finalRogue.phase)}}</strong></div><span>{{finalRogue.isCombatPhase()?'读取威胁并运行固件':'选择真实决策并继续'}}</span></div><p v-if="finalRogue.isCombatPhase()">Prepared Firmware 只载入代码；构建后再运行。战斗中三个威胁的已激活 / 未激活状态与 HP 来自真实 Simulation。Final Combat 保留 Snapshot / Rollback / Hot Reload。</p><p v-else>Reward / Branch / Rest 全部调用现有 FinalRogueRun 逻辑，模块与资源变化会真实流入下一场 Combat。</p><div class="api-guide"><div><code>enemy_ahead()</code><span>正前方有敌人时为 true</span></div><div><code>enemy_near()</code><span>敌人距离 ≤ 2（声呐后可到 3）</span></div><div><code>ranged_attack()</code><span>远程攻击射程内敌人</span></div><div><code>shield()</code><span>抵挡下一次伤害</span></div><div><code>dash()</code><span>快速冲刺/贴近</span></div><div><code>back()</code><span>后退一步，保持距离</span></div></div></section><section v-else-if="gameMode==='dungeon'&&!finalRogueActive" class="lesson-panel battle-advice"><div class="lesson-heading"><div><span class="panel-kicker">DUNGEON BRIEF</span><strong>{{tacticalMode?'战术要点':'地牢怎么走'}}</strong></div><span>{{tacticalMode?TACTICAL_SCENARIOS[tacticalIndex]?.lesson:'门与走廊是真实通道'}}</span></div><p>{{tacticalMode?TACTICAL_SCENARIOS[tacticalIndex]?.objective:'房间由走廊和门相连，move_forward() 会真实跨越门进入下一房间。Combat 房挡路的是 Slime，击败后穿过 Event 房拾取补给，最后抵达 Exit。'}}</p><ol><li v-for="tip in DEMO_DUNGEON_SCENARIO.tactics" :key="tip">{{tip}}</li></ol><div class="api-guide"><div><code>enemy_ahead()</code><span>敌人在正前方时为 true</span></div><div><code>wall_ahead()</code><span>前方是墙/房间边界时为 true</span></div><div><code>move_forward()</code><span>可穿过门与走廊</span></div><div><code>attack()</code><span>攻击正前方的敌人</span></div></div></section><section v-else class="lesson-panel"><div class="lesson-heading"><div><span class="panel-kicker">LEARNING DECK</span><strong>本关怎么想</strong></div><span>先成功，再改动</span></div><p>{{storyLessonText(currentLevel.id)}}</p><div class="api-guide"><div><code>move_forward()</code><span>向前走一格</span></div><div><code>wall_ahead()</code><span>检查前方是不是墙</span></div><div><code>turn_right()</code><span>向右转 90°</span></div><div><code>enemy_ahead()</code><span>检查前方有没有敌人</span></div><div><code>attack()</code><span>攻击正前方的敌人</span></div><div><code>ranged_attack()</code><span>攻击两格内的敌人</span></div><div><code>enemy_near()</code><span>敌人距离 ≤ 2 时为 true</span></div><div><code>shield()</code><span>抵挡下一次伤害</span></div></div><details class="syntax-guide" open><summary>RoboC++ 语法速查（可直接改示例）</summary><div class="syntax-grid"><div><b>每拍执行的入口</b><code>void update() {\n  move_forward();\n}</code><small>大括号包住程序；每一拍从 update 开始。</small></div><div><b>记住一个数字或开关</b><code>int n = 0;\nbool ready = false;\nn = n + 1;</code><small>int 是整数，bool 只有 true / false；赋值要用 =。</small></div><div><b>做选择</b><code>if (wall_ahead()) {\n  turn_right();\n} else {\n  move_forward();\n}</code><small>if 条件为真执行前半段，否则执行 else。</small></div><div><b>重复有限次</b><code>for (int i = 0; i &lt; 3; i = i + 1) {\n  wait();\n}</code><small>for 会重复执行；每次循环必须让 i 改变。</small></div><div><b>常用符号</b><code>== 相等   != 不等\n&amp;&amp; 且      || 或\n! 取反      // 注释</code><small>比较用 ==，单个 = 是保存新值。</small></div><div><b>可用模块</b><code>传感器：wall_ahead()  enemy_ahead()\nlow_hp()  enemy_near()  low_energy()\n数值：distance_to_enemy()  enemy_x()\nenemy_y()  steps_to_wall()\n动作：move_forward()  dash()\nturn_left()  turn_right()  attack()\nwait()  shield()  repair()  ranged_attack()</code><small>传感器只回答问题，动作才会改变机器人。</small></div></div></details></section>

        <section class="panel terminal">
          <div class="panel-head compact"><div><span class="panel-kicker">SYSTEM CONSOLE</span><strong>控制台</strong></div><span class="console-code">{{buildError||sim.status==='error'?'ERR':'SYS'}}</span></div>
          <div :class="['terminal-line',buildError||sim.status==='error'?'error':'']"><span class="prompt">›</span><span class="dot"></span>{{terminalMessage}}</div>
          <div v-if="sim.coreDump" class="core-dump">
            <div class="core-head"><strong>FAILURE CORE DUMP</strong><span>{{sim.coreDump.cause==='runtime_error'?'运行时错误':'机体损毁'}} · Tick {{sim.coreDump.tick}}</span></div>
            <div class="core-grid"><span>源码行 <b>{{sim.coreDump.sourceLine??'—'}}</b></span><span>位置 <b>{{sim.coreDump.robot.x}}, {{sim.coreDump.robot.y}}</b></span><span>朝向 <b>{{sim.coreDump.robot.dir}}</b></span><span>HP <b>{{sim.coreDump.robot.hp}}</b></span></div>
            <code>{{sim.coreDump.message}}</code>
            <div class="core-vars"><span v-for="(value,key) in sim.coreDump.variables" :key="key">{{key}}={{String(value)}}</span></div>
          </div>
          <div class="profiler"><span>PROFILER</span><b>Ticks {{sim.frames.length}}</b><b>Actions {{sim.frames.filter(item => !!item.action).length}}</b><b>Errors {{sim.frames.filter(item => !!item.error).length}}</b></div>
        </section>
      </div>

      <div class="right-column">
        <section :class="['panel','world',{threatened:enemyThreat,failed:sim.status==='failed'||sim.status==='error',success:sim.status==='success'}]">
          <div class="panel-head"><div><span class="panel-kicker">{{finalRogueActive?(finalRogue.isCombatPhase()?'行动视角':'决策中心'):gameMode==='dungeon'?'DUNGEON VIEW':expeditionScenarioActive?'EXPEDITION BATTLEFIELD':'SIMULATION CHAMBER'}}</span><strong>{{finalRogueActive?'FINAL ROGUE · '+finalRogueStageLabel(finalRogue.phase):tacticalMode?`战术房 · ${TACTICAL_SCENARIOS[tacticalIndex]?.title}`:gameMode==='dungeon'?'固定地牢 · Start → Combat → Event → Exit':expeditionScenarioActive?`远征战场 · ${expeditionScenario?.title??''}`:`模拟舱 · ${levelName(currentLevel.id)}`}}</strong></div><div class="coord"><span v-if="gameMode==='dungeon'" :title="`Room ${sim.robot.roomId??'corridor'}`">{{dungeonShortRoom(sim.robot.roomId)}}</span><span>X {{sim.robot.x}}</span><span>Y {{sim.robot.y}}</span><b>{{sim.robot.dir}}</b></div></div>
          <div class="objective"><span>{{finalRogueActive?(finalRogue.isCombatPhase()?'行动目标':'当前选择'):tacticalMode?'TACTICAL 目标':gameMode==='dungeon'?'DUNGEON 目标':expeditionScenarioActive?'远征目标':'关卡目标'}}</span><strong>{{finalRogueActive?(finalRogue.isCombatPhase()?'击破全部威胁并进入下一节点':'完成当前选择后继续远征'):tacticalMode?TACTICAL_SCENARIOS[tacticalIndex]?.objective:gameMode==='dungeon'?DEMO_DUNGEON_SCENARIO.objective:expeditionScenarioActive?expeditionScenario?.objective:currentLevel.objective}}</strong><em v-if="gameMode==='dungeon'&&sim.enemy.hp>0">{{sim.robot.roomId===sim.enemy.roomId?'同房遭遇':'战斗房待战'}} · {{enemyKindName(sim.enemy.kind)}} {{sim.enemy.hp}} HP</em><em v-else-if="sim.enemy.hp>0" :class="{danger:enemyThreat}">{{enemyThreat?'⚠ 接触危险':'史莱姆剩余'}} {{enemyThreat?'':' '+sim.enemy.hp+' HP'}}</em></div>
          <div v-if="gameMode==='dungeon'&&sim.dungeon&&(!finalRogueActive||finalRogue.isCombatPhase())" class="dungeon-wrap" :class="[tacticalThemeName(),finalRogueActive?'final-rogue-map':undefined]" aria-label="地牢地图">
          <div class="dungeon-stage" :style="{...dungeonCanvasStyle,transform:`scale(${finalRogueMapScale})`,transformOrigin:'center'}">
            <div v-if="(tacticalThemeName()==='theme-turret'||(finalShowcaseActive&&finalSectorIndex===2))&&sim.enemy.hp>0" class="dungeon-turret-exposure" :style="turretExposureStyle()"></div>
            <div v-if="tacticalThemeName()==='theme-guard'&&sim.enemy.hp>0" class="dungeon-guard-danger" :style="dungeonEnemyCenterStyle()"></div>
            <div v-for="room in dungeonRooms" :key="'shell-'+room.id" :class="['dungeon-room-shell','room-'+room.type,{active:room.active}]" :style="dungeonRoomShellStyle(room)"></div>
            <span v-for="room in dungeonRooms" :key="'label-'+room.id" :class="['dungeon-room-label','room-'+room.type,{active:room.active}]" :style="dungeonLabelStyle(room)"><i></i>{{dungeonRoomLabel(room.type)}}</span>
            <span v-if="!tacticalMode&&!finalRogueActive" v-for="marker in DUNGEON_MARKERS" :key="marker.id" :class="['dungeon-marker','marker-'+marker.id.toLowerCase()]" :style="dungeonMarkerStyle(marker.x,marker.y)">{{marker.id}}</span>
            <div v-for="cell in dungeonCells" :key="cell.x+'-'+cell.y" :class="['dungeon-cell',cell.kind,cell.zone]" :style="dungeonCellStyle(cell.x,cell.y)"></div>
            <span v-for="item in sim.items" :key="'item-'+item.x+'-'+item.y" :class="['dungeon-pickup',item.kind]" :style="dungeonPosStyle(item.x,item.y)">{{item.kind==='energy'?'⚡':'✚'}}</span>
            <img v-if="sim.exitPoint" :src="exitSprite" class="dungeon-entity dungeon-exit" :style="dungeonPosStyle(sim.exitPoint.x,sim.exitPoint.y)" alt="出口">
            <img v-if="!finalRogueActive&&sim.enemy.hp>0" :src="enemySpriteFor(sim.enemy.kind)" :class="['dungeon-entity','dungeon-enemy',`enemy-${sim.enemy.kind||'slime'}`]" :style="dungeonPosStyle(sim.enemy.x,sim.enemy.y)" alt="敌人">
            <img v-if="finalRogueActive" v-for="enemy in sim.enemies.filter(e=>e.hp>0&&e.x>=0)" :key="'enemy-'+enemy.x+'-'+enemy.y" :src="enemySpriteFor(enemy.kind)" :class="['dungeon-entity','dungeon-enemy',`enemy-${enemy.kind||'slime'}`]" :style="dungeonPosStyle(enemy.x,enemy.y)" :alt="finalRogueEnemyName(enemy.kind)">
            <img :src="robotSprite" :class="['dungeon-entity','dungeon-robot',`dir-${sim.robot.dir}`]" :style="dungeonPosStyle(sim.robot.x,sim.robot.y)" alt="机器人">
          </div>
        </div>
        <div v-else-if="finalRogueActive&&!finalRogue.isCombatPhase()" class="final-rogue-stage-panel">
          <span>当前阶段</span><b>{{finalRogueStageLabel(finalRogue.phase)}}</b>
          <p>决策与维护阶段不使用战斗地图，也不创建机器人/敌人 Simulation。</p>
          <dl><dt>HP</dt><dd>{{finalRogue.hp}} / {{finalRogue.maxHp}}</dd><dt>Energy</dt><dd>{{finalRogue.energy}} / {{finalRogue.maxEnergy}}</dd><dt>Modules</dt><dd><template v-if="finalRogue.modules.length"><b v-for="id in finalRogue.modules" :key="id" class="module-chip">{{finalRogueModuleTitle(id)}}</b></template><em v-else>标准机体</em></dd></dl>
          <p v-if="finalRogue.phase==='rest'">维护舱选择：战地维修 HP → {{finalRogueRepairPreview()}}，或快速充能 Energy → {{finalRogueChargePreview()}}。</p>
        </div>
        <div v-else class="map" :aria-label="expeditionScenarioActive?'远征地图':'关卡地图'">
            <div v-for="(row,y) in grid" :key="y" class="map-row">
              <div v-for="item in row" :key="item.x" :class="['tile',item.cell==='#'?'wall':'floor',item.cell==='E'?'exit':'',item.x===sim.robot.x&&item.y===sim.robot.y?'robot':'',item.x===sim.enemy.x&&item.y===sim.enemy.y&&sim.enemy.hp>0?'enemy':'',itemAt(item.x,item.y)?'has-item':'',fogEnabled&&!isVisible(item.x,item.y)?'fog':'']">
                <img v-if="item.x===sim.robot.x&&item.y===sim.robot.y" :src="robotSprite" :class="['robot-sprite',`dir-${sim.robot.dir}`]" alt="机器人">
                <img v-else-if="item.x===sim.enemy.x&&item.y===sim.enemy.y&&sim.enemy.hp>0" :src="enemySpriteFor(sim.enemy.kind)" class="enemy-sprite" :class="`enemy-${sim.enemy.kind||'slime'}`" alt="敌人">
                <img v-else-if="item.cell==='E'" :src="exitSprite" class="exit-sprite" alt="出口">
                <span v-else-if="itemAt(item.x,item.y)" class="item-pickup" :class="itemAt(item.x,item.y)!.kind">{{itemAt(item.x,item.y)!.kind==='energy'?'⚡':'+'}}</span>
              </div>
            </div>
          </div>
          <div v-if="gameMode==='dungeon'&&(!finalRogueActive||finalRogue.isCombatPhase())" class="legend dungeon-legend"><span><i class="room-key key-start"></i>起点</span><span><i class="room-key key-combat"></i>战斗</span><span><i class="room-key key-event"></i>事件</span><span><i class="room-key key-exit"></i>出口</span><span><i class="robot-key"></i>机器人</span><span><i class="enemy-key"></i>Slime</span></div><div v-else-if="!finalRogueActive||finalRogue.isCombatPhase()" class="legend"><span><i class="robot-key"></i>机器人</span><span><i class="enemy-key"></i>史莱姆</span><span><i class="exit-key"></i>出口</span><span><i class="wall-key"></i>墙体</span></div>
        </section>

        <section class="panel trace">
          <div class="panel-head"><div><span class="panel-kicker">EXECUTION TRACE</span><strong>执行追踪</strong></div><span class="frame-count">{{sim.frames.length}} 帧</span></div>
          <div class="timeline"><button v-for="(item,index) in sim.frames" :key="item.tick" :class="{active:index===selected}" @click="selected=index">{{item.tick}}</button><span v-if="!sim.frames.length" class="empty">运行固件后，这里会记录每一次决策</span></div>
          <div v-if="frame" class="inspector">
            <div class="inspect-grid">
              <div><small>动作 ACTION</small><strong>{{actionName(frame.action)}}</strong></div><div><small>源码 SOURCE</small><strong>{{frame.sourceLine?`第 ${frame.sourceLine} 行`:'-'}}</strong></div><div><small>坐标 POSITION</small><strong>{{frame.robot.x}}, {{frame.robot.y}}</strong></div><div><small>朝向 FACING</small><strong>{{frame.robot.dir}}</strong></div><div><small>生命 HP</small><strong>{{frame.robot.hp}}</strong></div>
            </div>
            <div class="detail"><div><small>传感器 SENSORS</small><code v-for="sensor in frame.sensors" :key="sensor.name">{{sensor.name}}() → {{String(sensor.value)}}</code><span v-if="!frame.sensors.length">本 Tick 未读取传感器</span></div><div><small>变量 VARIABLES</small><code v-for="(value,key) in frame.variables" :key="key">{{key}} = {{String(value)}}</code><span v-if="!Object.keys(frame.variables).length">暂无持久变量</span></div></div>
            <div v-if="frame.events.length" class="event"><span v-for="item in frame.events" :key="item">{{eventName(item)}}</span></div>
          </div>
        </section>
      </div>
    </section>

    <footer><span>{{finalRogueActive?('FINAL ROGUE / '+finalRogueStageLabel(finalRogue.phase)):gameMode==='expedition'?`EXPEDITION / 节点 ${Math.min(expedition.nodeIndex+1,expedition.route.length)} · ${expeditionNodeName(expeditionNode??'')}`:gameMode==='dungeon'?'DUNGEON / Fixed Slice · Start → Combat → Event → Exit':`STORY / ${currentLevel.id} · ${levelName(currentLevel.id)}`}}</span><span>编写 CODE → 构建 BUILD → 运行 RUN → 追踪 TRACE</span></footer>
  </main>
</template>
